(function(){if(!window.__hermes_register_book)return;window.__hermes_register_book("xeno-symposium-b",[{"sp": "N", "t": "SYMPOSIUM - Συμπόσιον φιλοσόφων Κ ΕΦΆΛΑΙΟΝ Α ʹ", "st": "1.1"}, {"sp": "N", "t": "Ἀλλ᾽ ἐμοὶ δοκεῖ τῶν καλῶν κἀγαθῶν ἀνδρῶν ἔργα οὐ μόνον τὰ μετὰ σπουδῆς πραττόμενα ἀξιομνημόνευτα εἶναι, ἀλλὰ καὶ τὰ ἐν ταῖς παιδιαῖς. οἷς δὲ παραγενόμενος ταῦτα γιγνώσκω δηλῶσαι βούλομαι.", "st": "1.1"}, {"sp": "N", "t": "ἦν μὲν γὰρ Παναθηναίων τῶν μεγάλων ἱπποδρομία, Καλλίας δὲ ὁ Ἱππονίκου ἐρῶν ἐτύγχανεν Αὐτολύκου παιδὸς ὄντος, καὶ νενικηκότα αὐτὸν παγκράτιον ἧκεν ἄγων ἐπὶ τὴν θέαν. ὡς δὲ ἡ ἱπποδρομία ἔληξεν, ἔχων τόν τε Αὐτόλυκον καὶ τὸν πατέρα αὐτοῦ ἀπήιει εἰς τὴν ἐν Πειραιεῖ οἰκίαν· συνείπετο δὲ αὐτῶι καὶ Νικήρατος.", "st": "1.2"}, {"sp": "N", "t": "ἰδὼν δὲ ὁμοῦ ὄντας Σωκράτην τε καὶ Κριτόβουλον καὶ Ἑρμογένην καὶ Ἀντισθένην καὶ Χαρμίδην, τοῖς μὲν ἀμφ᾽ Αὐτόλυκον ἡγεῖσθαί τινα ἔταξεν, αὐτὸς δὲ προσῆλθε τοῖς ἀμφὶ Σωκράτην, καὶ εἶπεν·", "st": "1.3"}, {"sp": "N", "t": "Εἰς καλόν γε ὑμῖν συντετύχηκα· ἑστιᾶν γὰρ μέλλω Αὐτόλυκον καὶ τὸν πατέρα αὐτοῦ. οἶμαι οὖν πολὺ ἂν τὴν κατασκευήν μοι λαμπροτέραν φανῆναι εἰ ἀνδράσιν ἐκκεκαθαρμένοις τὰς ψυχὰς ὥσπερ ὑμῖν ὁ ἀνδρὼν κεκοσμημένος εἴη μᾶλλον ἢ εἰ στρατηγοῖς καὶ ἱππάρχοις καὶ σπουδαρχίαις.", "st": "1.4"}, {"sp": "N", "t": "καὶ ὁ Σωκράτης εἶπεν· Ἀεὶ σὺ ἐπισκώπτεις ἡμᾶς καταφρονῶν, ὅτι σὺ μὲν Πρωταγόραι τε πολὺ ἀργύριον δέδωκας ἐπὶ σοφίαι καὶ Γοργίαι καὶ Προδίκωι καὶ ἄλλοις πολλοῖς, ἡμᾶς δ᾽ ὁρᾶις αὐτουργούς τινας τῆς φιλοσοφίας ὄντας.", "st": "1.5"}, {"sp": "N", "t": "καὶ ὁ Καλλίας, Καὶ πρόσθεν μέν γε, ἔφη, ἀπεκρυπτόμην ὑμᾶς ἔχων πολλὰ καὶ σοφὰ λέγειν, νῦν δέ, ἐὰν παρ᾽ ἐμοὶ ἦτε, ἐπιδείξω ὑμῖν ἐμαυτὸν πάνυ πολλῆς σπουδῆς ἄξιον ὄντα.", "st": "1.6"}, {"sp": "N", "t": "οἱ οὖν ἀμφὶ τὸν Σωκράτην πρῶτον μέν, ὥσπερ εἰκὸς ἦν, ἐπαινοῦντες τὴν κλῆσιν οὐχ ὑπισχνοῦντο συνδειπνήσειν· ὡς δὲ πάνυ ἀχθόμενος φανερὸς ἦν, εἰ μὴ ἕψοιντο, συνηκολούθησαν. ἔπειτα δὲ αὐτῶι οἱ μὲν γυμνασάμενοι καὶ χρισάμενοι, οἱ δὲ καὶ λουσάμενοι παρῆλθον.", "st": "1.7"}, {"sp": "N", "t": "Αὐτόλυκος μὲν οὖν παρὰ τὸν πατέρα ἐκαθέζετο, οἱ δ᾽ ἄλλοι, ὥσπερ εἰκός, κατεκλίθησαν. εὐθὺς μὲν οὖν ἐννοήσας τις τὰ γιγνόμενα ἡγήσατ᾽ ἂν φύσει βασιλικόν τι κάλλος εἶναι, ἄλλως τε καὶ ἂν μετ᾽ αἰδοῦς καὶ σωφροσύνης, καθάπερ Αὐτόλυκος τότε, κεκτῆταί τις αὐτό.", "st": "1.8"}, {"sp": "N", "t": "πρῶτον μὲν γάρ, ὥσπερ ὅταν φέγγος τι ἐν νυκτὶ φανῆι, πάντων προσάγεται τὰ ὄμματα, οὕτω καὶ τότε τοῦ Αὐτολύκου τὸ κάλλος πάντων εἷλκε τὰς ὄψεις πρὸς αὐτόν· ἔπειτα τῶν ὁρώντων οὐδεὶς οὐκ ἔπασχέ τι τὴν ψυχὴν ὑπ᾽ ἐκείνου. οἱ μέν γε σιωπηρότεροι ἐγίγνοντο, οἱ δὲ καὶ ἐσχηματίζοντό πως.", "st": "1.9"}, {"sp": "N", "t": "πάντες μὲν οὖν οἱ ἐκ θεῶν του κατεχόμενοι ἀξιοθέατοι δοκοῦσιν εἶναι· ἀλλ᾽ οἱ μὲν ἐξ ἄλλων πρὸς τὸ γοργότερ⟨όν⟩ τε ὁρᾶσθαι καὶ φοβερώτερον φθέγγεσθαι καὶ σφοδρότεροι εἶναι φέρονται, οἱ δ᾽ ὑπὸ τοῦ σώφρονος ἔρωτος ἔνθεοι τά τε ὄμματα φιλοφρονεστέρως ἔχουσι καὶ τὴν φωνὴν πραιοτέραν ποιοῦνται καὶ τὰ σχήματα εἰς τὸ ἐλευθεριώτερον ἄγουσιν. ἃ δὴ καὶ Καλλίας τότε διὰ τὸν ἔρωτα πράττων ἀξιοθέατος ἦν τοῖς τετελεσμένοις τούτωι τῶι θεῶι.", "st": "1.10"}, {"sp": "N", "t": "ἐκεῖνοι μὲν οὖν σιωπῆι ἐδείπνουν, ὥσπερ τοῦτο ἐπιτεταγμένον αὐτοῖς ὑπὸ κρείττονός τινος. Φίλιππος δ᾽ ὁ γελωτοποιὸς κρούσας τὴν θύραν εἶπε τῶι ὑπακούσαντι εἰσαγγεῖλαι ὅστις τε εἴη καὶ δι᾽ ὅ τι κατάγεσθαι βούλοιτο, συνεσκευασμένος τε παρεῖναι ἔφη πάντα τὰ ἐπιτήδεια ὥστε δειπνεῖν τἀλλότρια, καὶ τὸν παῖδα δὲ ἔφη πάνυ πιέζεσθαι διά τε τὸ φέρειν μηδὲν καὶ διὰ τὸ ἀνάριστον εἶναι.", "st": "1.11"}, {"sp": "N", "t": "ὁ οὖν Καλλίας ἀκούσας ταῦτα εἶπεν· Ἀλλὰ μέντοι, ὦ ἄνδρες, αἰσχρὸν στέγης γε φθονῆσαι· εἰσίτω οὖν. καὶ ἅμα ἀπέβλεψεν εἰς τὸν Αὐτόλυκον, δῆλον ὅτι ἐπισκοπῶν τί ἐκείνωι δόξειε τὸ σκῶμμα εἶναι·", "st": "1.12"}, {"sp": "N", "t": "ὁ δὲ στὰς ἐπὶ τῶι ἀνδρῶνι ἔνθα τὸ δεῖπνον ἦν εἶπεν· Ὅτι μὲν γελωτοποιός εἰμι ἴστε πάντες· ἥκω δὲ προθύμως νομίσας γελοιότερον εἶναι τὸ ἄκλητον ἢ τὸ κεκλημένον ἐλθεῖν ἐπὶ τὸ δεῖπνον. Κατακλίνου τοίνυν, ἔφη ὁ Καλλίας. καὶ γὰρ οἱ παρόντες σπουδῆς μέν, ὡς ὁρᾶις, μεστοί, γέλωτος δὲ ἴσως ἐνδεέστεροι.", "st": "1.13"}, {"sp": "N", "t": "δειπνούντων δὲ αὐτῶν ὁ Φίλιππος γελοῖόν τι εὐθὺς ἐπεχείρει λέγειν, ἵνα δὴ ἐπιτελοίη ὧνπερ ἕνεκα ἐκαλεῖτο ἑκάστοτε ἐπὶ τὰ δεῖπνα. ὡς δ᾽ οὐκ ἐκίνησε γέλωτα, τότε μὲν ἀχθεσθεὶς φανερὸς ἐγένετο. αὖθις δ᾽ ὀλίγον ὕστερον ἄλλο τι γελοῖον ἐβούλετο λέγειν. ὡς δὲ οὐδὲ τότε ἐγέλασαν ἐπ᾽ αὐτῶι, ἐν τῶι μεταξὺ παυσάμενος τοῦ δείπνου συγκαλυψάμενος κατέκειτο.", "st": "1.14"}, {"sp": "N", "t": "καὶ ὁ Καλλίας, Τί τοῦτ᾽, ἔφη, ὦ Φίλιππε; ἀλλ᾽ ἢ ὀδύνη σε εἴληφε; καὶ ὃς ἀναστενάξας εἶπε· Ναὶ μὰ Δί᾽, ἔφη, ὦ Καλλία, μεγάλη γε· ἐπεὶ γὰρ γέλως ἐξ ἀνθρώπων ἀπόλωλεν, ἔρρει τὰ ἐμὰ πράγματα. πρόσθεν μὲν γὰρ τούτου ἕνεκα ἐκαλούμην ἐπὶ τὰ δεῖπνα, ἵνα εὐφραίνοιντο οἱ συνόντες δι᾽ ἐμὲ γελῶντες· νῦν δὲ τίνος ἕνεκα καὶ καλεῖ μέ τις; οὔτε γὰρ ἔγωγε σπουδάσαι ἂν δυναίμην μᾶλλον ἤπερ ἀθάνατος γενέσθαι, οὔτε μὴν ὡς ἀντικληθησόμενος καλεῖ μέ τις, ἐπεὶ πάντες ἴσασιν ὅτι ἀρχὴν οὐδὲ νομίζεται εἰς τὴν ἐμὴν οἰκίαν δεῖπνον προσφέρεσθαι. καὶ ἅμα λέγων ταῦτα ἀπεμύττετό τε καὶ τῆι φωνῆι σαφῶς κλαίειν ἐφαίνετο.", "st": "1.15"}, {"sp": "N", "t": "πάντες μὲν οὖν παρεμυθοῦντό τε αὐτὸν ὡς αὖθις γελασόμενοι καὶ δειπνεῖν ἐκέλευον, Κριτόβουλος δὲ καὶ ἐξεκάγχασεν ἐπὶ τῶι οἰκτισμῶι αὐτοῦ. ὁ δ᾽ ὡς ἤισθετο τοῦ γέλωτος, ἀνεκαλύψατό τε καὶ τῆι ψυχῆι παρακελευσάμενος θαρρεῖν, ὅτι ἔσονται συμβολαί, πάλιν ἐδείπνει.", "st": "1.16"}, {"sp": "N", "t": "Ὡς δ᾽ ἀφηιρέθησαν αἱ τράπεζαι καὶ ἔσπεισάν τε καὶ ἐπαιάνισαν, ἔρχεται αὐτοῖς ἐπὶ κῶμον Συρακόσιός τις ἄνθρωπος, ἔχων τε αὐλητρίδα ἀγαθὴν καὶ ὀρχηστρίδα τῶν τὰ θαύματα δυναμένων ποιεῖν, καὶ παῖδα πάνυ γε ὡραῖον καὶ πάνυ καλῶς κιθαρίζοντα καὶ ὀρχούμενον. ταῦτα δὲ καὶ ἐπιδεικνὺς ὡς ἐν θαύματι ἀργύριον ἐλάμβανεν.", "st": "2.1"}, {"sp": "N", "t": "ἐπεὶ δὲ αὐτοῖς ἡ αὐλητρὶς μὲν ηὔλησεν, ὁ δὲ παῖς ἐκιθάρισε, καὶ ἐδόκουν μάλα ἀμφότεροι ἱκανῶς εὐφραίνειν, εἶπεν ὁ Σωκράτης· Νὴ Δί᾽, ὦ Καλλία, τελέως ἡμᾶς ἑστιᾶις. οὐ γὰρ μόνον δεῖπνον ἄμεμπτον παρέθηκας, ἀλλὰ καὶ θεάματα καὶ ἀκροάματα ἤδιστα παρέχεις.", "st": "2.2"}, {"sp": "N", "t": "καὶ ὃς ἔφη· Τί οὖν εἰ καὶ μύρον τις ἡμῖν ἐνέγκαι, ἵνα καὶ εὐωδίαι ἑστιώμεθα; Μηδαμῶς, ἔφη ὁ Σωκράτης. ὥσπερ γάρ τοι ἐσθὴς ἄλλη μὲν γυναικί, ἄλλη δὲ ἀνδρὶ καλή, οὕτω καὶ ὀσμὴ ἄλλη μὲν ἀνδρί, ἄλλη δὲ γυναικὶ πρέπει. καὶ γὰρ ἀνδρὸς μὲν δήπου ἕνεκα ἀνὴρ οὐδεὶς μύρωι χρίεται. αἱ μέντοι γυναῖκες ἄλλως τε καὶ ἂν νύμφαι τύχωσιν οὖσαι, ὥσπερ ἡ Νικηράτου τοῦδε καὶ ἡ Κριτοβούλου, μύρου μὲν τί καὶ προσδέονται;", "st": "2.3"}, {"sp": "N", "t": "αὐταὶ γὰρ τούτου ὄζουσιν· ἐλαίου δὲ τοῦ ἐν γυμνασίοις ὀσμὴ καὶ παροῦσα ἡδίων ἢ μύρου γυναιξὶ καὶ ἀποῦσα ποθεινοτέρα. καὶ γὰρ δὴ μύρωι μὲν ὁ ἀλειψάμενος καὶ δοῦλος καὶ ἐλεύθερος εὐθὺς ἅπας ὅμοιον ὄζει· αἱ δ᾽ ἀπὸ τῶν ἐλευθερίων μόχθων ὀσμαὶ ἐπιτηδευμάτων τε πρῶτον χρηστῶν καὶ χρόνου πολλοῦ δέονται, εἰ μέλλουσιν ἡδεῖαί τε καὶ ἐλευθέριοι ἔσεσθαι. καὶ ὁ Λύκων εἶπεν· Οὐκοῦν νέοις μὲν ἂν εἴη ταῦτα· ἡμᾶς δὲ τοὺς μηκέτι γυμναζομένους τίνος ὄζειν δεήσει; Καλοκἀγαθίας νὴ Δί᾽, ἔφη ὁ Σωκράτης. Καὶ πόθεν ἄν τις τοῦτο τὸ χρῖμα λάβοι; Οὐ μὰ Δί᾽, ἔφη, οὐ παρὰ τῶν μυροπωλῶν. Ἀλλὰ πόθεν δή; Ὁ μὲν Θέογνις ἔφη· Ἐσθλῶν μὲν γὰρ ἀπ᾽ ἐσθλὰ διδάξεαι· ἢν δὲ κακοῖσι συμμίσγηις, ἀπολεῖς καὶ τὸν ἐόντα νόον.", "st": "2.4"}, {"sp": "N", "t": "καὶ ὁ Λύκων εἶπεν· Ἀκούεις ταῦτα, ὦ υἱέ; Ναὶ μὰ Δί᾽, ἔφη ὁ Σωκράτης, καὶ χρῆταί γε. ἐπεὶ γοῦν νικηφόρος ἐβούλετο τοῦ παγκρατίου γενέσθαι, σὺν σοὶ σκεψάμενος ⟨...⟩ αὖ, ὃς ἂν δοκῆι αὐτῶι ἱκανώτατος εἶναι εἰς ⟨τὸ⟩ ταῦτα ἐπιτηδεῦσαι, τούτωι συνέσται.", "st": "2.5"}, {"sp": "N", "t": "ἐνταῦθα δὴ πολλοὶ ἐφθέγξαντο· καὶ ὁ μέν τις αὐτῶν εἶπε·Ποῦ οὖν εὑρήσει τούτου διδάσκαλον; ὁ δέ τις ὡς οὐδὲ διδακτὸν τοῦτο εἴη, ἕτερος δέ τις ὡς εἴπερ τι καὶ ἄλλο καὶ τοῦτο μαθητόν.", "st": "2.6"}, {"sp": "N", "t": "ὁ δὲ Σωκράτης ἔφη· Τοῦτο μὲν ἐπειδὴ ἀμφίλογόν ἐστιν, εἰς αὖθις ἀποθώμεθα· νυνὶ δὲ τὰ προκείμενα ἀποτελῶμεν. ὁρῶ γὰρ ἔγωγε τήνδε τὴν ὀρχηστρίδα ἐφεστηκυῖαν καὶ τροχούς τινα αὐτῆι προσφέροντα.", "st": "2.7"}, {"sp": "N", "t": "ἐκ τούτου δὴ ηὔλει μὲν αὐτῆι ἡ ἑτέρα, παρεστηκὼς δέ τις τῆι ὀρχηστρίδι ἀνεδίδου τοὺς τροχοὺς μέχρι δώδεκα. ἡ δὲ λαμβάνουσα ἅμα τε ὠρχεῖτο καὶ ἀνερρίπτει δονουμένους συντεκμαιρομένη ὅσον ἔδει ῥιπτεῖν ὕψος ὡς ἐν ῥυθμῶι δέχεσθαι αὐτούς.", "st": "2.8"}, {"sp": "N", "t": "καὶ ὁ Σωκράτης εἶπεν· Ἐν πολλοῖς μέν, ὦ ἄνδρες, καὶ ἄλλοις δῆλον καὶ ἐν οἷς δ᾽ ἡ παῖς ποιεῖ ὅτι ἡ γυναικεία φύσις οὐδὲν χείρων τῆς τοῦ ἀνδρὸς οὖσα τυγχάνει, γνώμης δὲ καὶ ἰσχύος δεῖται. ὥστε εἴ τις ὑμῶν γυναῖκα ἔχει, θαρρῶν διδασκέτω ὅ τι βούλοιτ᾽ ἂν αὐτῆι ἐπισταμένηι χρῆσθαι.", "st": "2.9"}, {"sp": "N", "t": "καὶ ὁ Ἀντισθένης, Πῶς οὖν, ἔφη, ὦ Σώκρατες, οὕτω γιγνώσκων οὐ καὶ σὺ παιδεύεις Ξανθίππην, ἀλλὰ χρῆι γυναικὶ τῶν οὐσῶν, οἶμαι δὲ καὶ τῶν γεγενημένων καὶ τῶν ἐσομένων χαλεπωτάτηι; Ὅτι, ἔφη, ὁρῶ καὶ τοὺς ἱππικοὺς βουλομένους γενέσθαι οὐ τοὺς εὐπειθεστάτους ἀλλὰ τοὺς θυμοειδεῖς ἵππους κτωμένους. νομίζουσι γάρ, ἂν τοὺς τοιούτους δύνωνται κατέχειν, ῥαιδίως τοῖς γε ἄλλοις ἵπποις χρήσεσθαι. κἀγὼ δὴ βουλόμενος ἀνθρώποις χρῆσθαι καὶ ὁμιλεῖν ταύτην κέκτημαι, εὖ εἰδὼς ὄτι εἰ ταύτην ὑποίσω, ῥαιδίως τοῖς γε ἀλλοις ἅπασιν ἀνθρώποις συνέσομαι. καὶ οὗτος μὲν δὴ ὁ λόγος οὐκ ἄπο τοῦ σκοποῦ ἔδοξεν εἰρῆσθαι.", "st": "2.10"}, {"sp": "N", "t": "μετὰ δὲ τοῦτο κύκλος εἰσηνέχθη περίμεστος ξιφῶν ὀρθῶν. εἰς οὖν ταῦτα ἡ ὀρχηστρὶς ἐκυβίστα τε καὶ ἐξεκυβίστα ὑπὲρ αὐτῶν. ὥστε οἱ μὲν θεώμενοι ἐφοβοῦντο μή τι πάθηι, ἡ δὲ θαρρούντως τε καὶ ἀσφαλῶς ταῦτα διεπράττετο.", "st": "2.11"}, {"sp": "N", "t": "καὶ ὁ Σωκράτης καλέσας τὸν Ἀντισθένην εἶπεν· Οὔτοι τούς γε θεωμένους τάδε ἀντιλέξειν ἔτι οἴομαι, ὡς οὐχὶ καὶ ἡ ἀνδρεία διδακτόν, ὁπότε αὕτη καίπερ γυνὴ οὖσα οὕτω τολμηρῶς εἰς τὰ ξίφη ἵεται.", "st": "2.12"}, {"sp": "N", "t": "καὶ ὁ Ἀντισθένης εἶπεν· Ἆρ᾽ οὖν καὶ τῶιδε τῶι Συρακοσίωι κράτιστον ἐπιδείξαντι τῆι πόλει τὴν ὀρχηστρίδα εἰπεῖν, ἐὰν διδῶσιν αὐτῶι Ἀθηναῖοι χρήματα, ποιήσειν πάντας Ἀθηναίους τολμᾶν ὁμόσε ταῖς λόγχαις ἰέναι;", "st": "2.13"}, {"sp": "N", "t": "καὶ ὁ Φίλιππος, Νὴ Δί᾽, ἔφη καὶ μὴν ἔγωγε ἡδέως ἂν θεώιμην Πείσανδρον τὸν δημηγόρον μανθάνοντα κυβιστᾶν εἰς τὰς μαχαίρας, ὃς νῦν διὰ τὸ μὴ δύνασθαι λόγχαις ἀντιβλέπειν οὐδὲ συστρατεύεσθαι ἐθέλει. ἐκ τούτου ὁ παῖς ὠρχήσατο.", "st": "2.14"}, {"sp": "N", "t": "καὶ ὁ Σωκράτης εἶπεν· Εἴδετ᾽, ἔφη, ὡς καλὸς ⟨ὁ⟩ παῖς ὢν ὅμως σὺν τοῖς σχήμασιν ἔτι καλλίων φαίνεται ἢ ὅταν ἡσυχίαν ἔχηι; καὶ ὁ Χαρμίδης εἶπεν· Ἐπαινοῦντι ἔοικας τὸν ὀρχηστοδιδάσκαλον.", "st": "2.15"}, {"sp": "N", "t": "Ναὶ μὰ τὸν Δί᾽, ἔφη ὁ Σωκράτης· καὶ γὰρ ἄλλο τι προσενενόησα, ὅτι οὐδὲν ἀργὸν τοῦ σώματος ἐν τῆι ὀρχήσει ἦν, ἀλλ᾽ ἅμα καὶ τράχηλος καὶ σκέλη καὶ χεῖρες ἐγυμνάζοντο, ὥσπερ χρὴ ὀρχεῖσθαι τὸν μέλλοντα εὐφορώτερον τὸ σῶμα ἕξειν. καὶ ἐγὼ μέν, ἔφη, πάνυ ἂν ἡδέως, ὦ Συρακόσιε, μάθοιμι τὰ σχήματα παρὰ σοῦ. καὶ ὅς, Τί οὖν χρήσηι αὐτοῖς; ἔφη.", "st": "2.16"}, {"sp": "N", "t": "Ὀρχήσομαι νὴ Δία. ἐνταῦθα δὴ ἐγέλασαν ἅπαντες. καὶ ὁ Σωκράτης μάλα ἐσπουδακότι τῶι προσώπωι, Γελᾶτε, ἔφη, ἐπ᾽ ἐμοί; πότερον ἐπὶ τούτωι εἰ βούλομαι γυμναζόμενος μᾶλλον ὑγιαίνειν ἢ εἰ ἥδιον ἐσθίειν καὶ καθεύδειν ἢ εἰ τοιούτων γυμνασίων ἐπιθυμῶ, μὴ ὥσπερ οἱ δολιχοδρόμοι τὰ σκέλη μὲν παχύνονται, τοὺς ὤμους δὲ λεπτύνονται, μηδ᾽ ὥσπερ οἱ πύκται τοὺς μὲν ὤμους παχύνονται, τὰ δὲ σκέλη λεπτύνονται, ἀλλὰ παντὶ διαπονῶν τῶι σώματι πᾶν ἰσόρροπον ποιεῖν;", "st": "2.17"}, {"sp": "N", "t": "ἢ ἐπ᾽ ἐκείνωι γελᾶτε, ὅτι οὐ δεήσει με συγγυμναστὴν ζητεῖν, οὐδ᾽ ἐν ὄχλωι πρεσβύτην ὄντα ἀποδύεσθαι, ἀλλ᾽ ἀρκέσει μοι οἶκος ἑπτάκλινος, ὥσπερ καὶ νῦν τῶιδε τῶι παιδὶ ἤρκεσε τόδε τὸ οἴκημα ἐνιδρῶσαι, καὶ χειμῶνος μὲν ἐν στέγηι γυμνάσομαι, ὅταν δὲ ἄγαν καῦμα ἦι, ἐν σκιᾶι;", "st": "2.18"}, {"sp": "N", "t": "ἢ τόδε γελᾶτε, εἰ μείζω τοῦ καιροῦ τὴν γαστέρα ἔχων μετριωτέραν βούλομαι ποιῆσαι αὐτήν; ἢ οὐκ ἴστε ὅτι ἔναγχος ἕωθεν Χαρμίδης οὑτοσὶ κατέλαβέ με ὀρχούμενον; Ναὶ μὰ τὸν Δί᾽, ἔφη ὁ Χαρμίδης· καὶ τὸ μέν γε πρῶτον ἐξεπλάγην καὶ ἔδεισα μὴ μαίνοιο· ἐπεὶ δέ σου ἤκουσα ὅμοια οἷς νῦν λέγεις, καὶ αὐτὸς ἐλθὼν οἴκαδε ὠρχούμην μὲν οὔ, οὐ γὰρ πώποτε τοῦτ᾽ ἔμαθον, ἐχειρονόμουν δέ· ταῦτα γὰρ ἡπιστάμην.", "st": "2.19"}, {"sp": "N", "t": "Νὴ Δί᾽, ἔφη ὁ Φίλιππος, καὶ γὰρ οὖν οὕτω τὰ σκέλη τοῖς ὤμοις φαίνει ἰσοφόρα ἔχειν ὥστε δοκεῖς ἐμοί, κἂν εἰ τοῖς ἀγορανόμοις ἀφισταίης ὥσπερ ἄρτους τὰ κάτω πρὸς τὰ ἄνω, ἀζήμιος ἂν γενέσθαι. καὶ ὁ Καλλίας εἶπεν· Ὦ Σώκρατες, ἐμὲ μὲν παρακάλει, ὅταν μέλληις μανθάνειν ὀρχεῖσθαι, ἵνα σοι ἀντιστοιχῶ τε καὶ συμμανθάνω.", "st": "2.20"}, {"sp": "N", "t": "Ἄγε δή, ἔφη ὁ Φίλιππος, καὶ ἐμοὶ αὐλησάτω, ἵνα καὶ ἐγὼ ὀρχήσωμαι. ἐπειδὴ δ᾽ ἀνέστη, διῆλθε μιμούμενος τήν τε τοῦ παιδὸς καὶ τὴν τῆς παιδὸς ὄρχησιν.", "st": "2.21"}, {"sp": "N", "t": "καὶ πρῶτον μὲν ὅτι ἐπήινεσαν ὡς ὁ παῖς σὺν τοῖς σχήμασιν ἔτι καλλίων ἐφαίνετο, ἀνταπέδειξεν ὅ τι κινοίη τοῦ σώματος ἅπαν τῆς φύσεως γελοιότερον; ὅτι δ᾽ ἡ παῖς εἰς τοὔπισθεν καμπτομένη τροχοὺς ἐμιμεῖτο, ἐκεῖνος ταὐτὰ εἰς τὸ ἔμπροσθεν ἐπικύπτων μιμεῖσθαι τροχοὺς ἐπειρᾶτο. τέλος δ᾽ ὅτι τὸν παῖδ᾽ ἐπήινουν ὡς ἐν τῆι ὀρχήσει ἅπαν τὸ σῶμα γυμνάζοι, κελεύσας τὴν αὐλητρίδα θάττονα ῥυθμὸν ἐπάγειν ἵει ἅμα πάντα καὶ σκέλη καὶ χεῖρας καὶ κεφαλήν.", "st": "2.22"}, {"sp": "N", "t": "ἐπειδὴ δὲ ἀπειρήκει, κατακλινόμενος εἶπε· Τεκμήριον, ὦ ἄνδρες, ὅτι καλῶς γυμνάζει καὶ τὰ ἐμὰ ὀρχήματα. ἐγὼ γοῦν διψῶ· καὶ ὁ παῖς ἐγχεάτω μοι τὴν μεγάλην φιάλην. Νὴ Δί᾽, ἔφη ὁ Καλλίας, καὶ ἡμῖν γε, ἐπεὶ καὶ ἡμεῖς διψῶμεν ἐπὶ σοὶ γελῶντες.", "st": "2.23"}, {"sp": "N", "t": "ὁ δ᾽ αὖ Σωκράτης εἶπεν· Ἀλλὰ πίνειν μέν, ὦ ἄνδρες, καὶ ἐμοὶ πάνυ δοκεῖ· τῶι γὰρ ὄντι ὁ οἶνος ἄρδων τὰς ψυχὰς τὰς μὲν λύπας, ὥσπερ ὁ μανδραγόρας τοὺς ἀνθρώπους, κοιμίζει, τὰς δὲ φιλοφροσύνας, ὣσπερ ἔλαιον φλόγα, ἐγείρει.", "st": "2.24"}, {"sp": "N", "t": "δοκεῖ μέντοι μοι καὶ τὰ τῶν ἀνδρῶν σώματα ταὐτὰ πάσχειν ἅπερ καὶ τὰ τῶν ἐν γῆι φυομένων. καὶ γὰρ ἐκεῖνα, ὅταν μὲν ὁ θεὸς αὐτὰ ἄγαν ἁθρόως ποτίζηι, οὐ δύναται ὀρθοῦσθαι οὐδὲ ταῖς αὔραις διαπνεῖσθαι· ὅταν δ᾽ ὅσωι ἥδεται τοσοῦτον πίνηι, καὶ μάλα ὀρθά τε αὔξεται καὶ θάλλοντα ἀφικνεῖται εἰς τὴν καρπογονίαν.", "st": "2.25"}, {"sp": "N", "t": "οὕτω δὲ καὶ ἡμεῖς ἂν μὲν ἁθρόον τὸ ποτὸν ἐγχεώμεθα, ταχὺ ἡμῖν καὶ τὰ σώματα καὶ αἱ γνῶμαι σφαλοῦνται, καὶ οὐδὲ ἀναπνεῖν, μὴ ὅτι λέγειν τι δυνησόμεθα· ἂν δὲ ἡμῖν οἱ παῖδες μικραῖς κύλιξι πυκνὰ ἐπιψακάζωσιν, ἵνα καὶ ἐγὼ ἐν Γοργιείοις ῥήμασιν εἴπω, οὕτως οὐ βιαζόμενοι μεθύειν ὑπὸ τοῦ οἴνου ἀλλ᾽ ἀναπειθόμενοι πρὸς τὸ παιγνιωδέστερον ἀφιξόμεθα.", "st": "2.26"}, {"sp": "N", "t": "ἐδόκει μὲν δὴ ταῦτα πᾶσι· προσέθηκε δὲ ὁ Φίλιππος ὡς χρὴ τοὺς οἰνοχόους μιμεῖσθαι τοὺς ἀγαθοὺς ἁρματηλάτας, θᾶττον περιελαύνοντας τὰς κύλικας. οἱ μὲν δὴ οἰνοχόοι οὕτως ἐποίουν.", "st": "2.27"}, {"sp": "N", "t": "Ἐκ δὲ τούτου συνηρμοσμένηι τῆι λύραι πρὸς τὸν αὐλὸν ἐκιθάρισεν ὁ παῖς καὶ ἦισεν. ἔνθα δὴ ἐπήινεσαν μὲν ἅπαντες· ὁ δὲ Χαρμίδης καὶ εἶπεν· Ἀλλ᾽ ἐμοὶ μὲν δοκεῖ, ὦ ἄνδρες, ὥσπερ Σωκράτης ἔφη τὸν οἶνον, οὕτως καὶ αὕτη ἡ κρᾶσις τῶν τε παίδῶν τῆς ὥρας καὶ τῶν φθόγγων τὰς μὲν λύπας κοιμίζειν, τὴν δ᾽ ἀφροδίτην ἐγείρειν.", "st": "3.1"}, {"sp": "N", "t": "ἐκ τούτου δὲ πάλιν εἶπεν ὁ Σωκράτης· Οὗτοι μὲν δή, ὦ ἄνδρες, ἱκανοὶ τέρπειν ἡμᾶς φαίνονται· ἡμεῖς δὲ τούτων οἶδ᾽ ὅτι πολὺ βελτίονες οἰόμεθα εἶναι· οὐκ αἰσχρὸν οὖν εἰ μήδ᾽ ἐπιχειρήσομεν συνόντες ὠφελεῖν τι ἢ εὐφραίνειν ἀλλήλους; Ἐντεῦθεν εἶπαν πολλοί· Σὺ τοίνυν ἡμῖν ἐξηγοῦ ποίων λόγων ἁπτόμενοι μάλιστ᾽ ἂν ταῦτα ποιοῖμεν.", "st": "3.2"}, {"sp": "N", "t": "ἐγὼ μὲν τοίνυν, ἔφη, ἥδιστ᾽ ἂν ἀπολάβοιμι παρὰ Καλλίου τὴν ὑπόσχεσιν. ἔφη γὰρ δήπου, εἰ συνδειπνοῖμεν, ἐπιδείξειν τὴν αὑτοῦ σοφίαν. Καὶ ἐπιδείξω γε, ἔφη, ἐὰν καὶ ὑμεῖς ἅπαντες εἰς μέσον φέρητε ὅ τι ἕκαστος ἐπίστασθε ἀγαθόν. Ἀλλ᾽ οὐδείς σοι, ἔφη, ἀντιλέγει τὸ μὴ οὐ λέξειν ὅ τι ἕκαστος ἡγεῖται πλείστου ἄξιον ἐπίστασθαι.", "st": "3.3"}, {"sp": "N", "t": "Ἐγὼ μὲν τοίνυν, ἔφη, λέγω ὑμῖν ἐφ᾽ ὧι μέγιστον φρονῶ. ἀνθρώπους γὰρ οἶμαι ἱκανὸς εἶναι βελτίους ποιεῖν. καὶ ὁ Ἀντισθένης εἶπε· Πότερον τέχνην τινὰ βαναυσικὴν ἢ καλοκἀγαθίαν διδάσκων; Εἰ καλοκἀγαθία ἐστὶν ἡ δικαιοσύνη. Νὴ Δί᾽, ἔφη ὁ Ἀντισθένης, ἥ γε ἀναμφιλογωτάτη· ἐπεί τοι ἀνδρεία μὲν καὶ σοφία ἔστιν ὅτε βλαβερὰ καὶ φίλοις καὶ πόλει δοκεῖ εἶναι, ἡ δὲ δικαιοσύνη οὐδὲ καθ᾽ ἓν συμμίγνυται τῆι ἀδικίαι.", "st": "3.4"}, {"sp": "N", "t": "Ἐπειδὰν τοίνυν καὶ ὑμῶν ἕκαστος εἴπηι ὅ τι ὠφέλιμον ἔχει, τότε κἀγὼ οὐ φθονήσω εἰπεῖν τὴν τέχνην δι᾽ ἧς τοῦτο ἀπεργάζομαι. ἀλλὰ σὺ αὖ, ἔφη, λέγε, ὦ Νικήρατε, ἐπὶ ποίαι ἐπιστήμηι μέγα φρονεῖς. καὶ ὃς εἶπεν· Ὁ πατὴρ ὁ ἐπιμελούμενος ὅπως ἀνὴρ ἀγαθὸς γενοίμην ἠνάγκασέ με πάντα τὰ Ὁμήρου ἔπη μαθεῖν· καὶ νῦν δυναίμην ἂν Ἰλιάδα ὅλην καὶ Ὀδύσσειαν ἀπὸ στόματος εἰπεῖν.", "st": "3.5"}, {"sp": "N", "t": "Ἐκεῖνο δ᾽, ἔφη ὁ Ἀντισθένης, λέληθέ σε, ὅτι καὶ οἱ ῥαψωιδοὶ πάντες ἐπίστανται ταῦτα τὰ ἔπη; Καὶ πῶς ἄν, ἔφη, λελήθοι ἀκροώμενόν γε αὐτῶν ὀλίγου ἀν᾽ ἑκάστην ἡμέραν; Οἶσθά τι οὖν ἔθνος, ἔφη, ἠλιθιώτερον ῥαψωιδῶν; Οὐ μὰ τὸν Δί᾽, ἔφη ὁ Νικήρατος, οὔκουν ἔμοιγε δοκῶ. Δῆλον γάρ, ἔφη ὁ Σωκράτης, ὅτι τὰς ὑπονοίας οὐκ ἐπίστανται. σὺ δὲ Στησιμβρότωι τε καὶ Ἀναξιμάνδρωι καὶ ἄλλοις πολλοῖς πολὺ δέδωκας ἀργύριον, ὥστε οὐδέν σε τῶν πολλοῦ ἀξίων λέληθε.", "st": "3.6"}, {"sp": "N", "t": "τί γὰρ σύ, ἔφη, ὦ Κριτόβουλε, ἐπὶ τίνι μέγιστον φρονεῖς; Ἐπὶ κάλλει, ἔφη. Ἦ οὖν καὶ σύ, ἔφη ὁ Σωκράτης, ἕξεις λέγειν ὅτι τῶι σῶι κάλλει ἱκανὸς εἶ βελτίους ἡμᾶς ποιεῖν; Εἰ δὲ μή, δῆλόν γε ὅτι φαῦλος φανοῦμαι.", "st": "3.7"}, {"sp": "N", "t": "Τί γὰρ σύ, εἶπεν, ἐπὶ τίνι μέγα φρονεῖς, ὦ Ἀντίσθενες; Ἐπὶ πλούτωι, ἔφη. ὁ μὲν δὴ Ἑρμογένης ἀνήρετο εἰ πολὺ εἴη αὐτῶι ἀργύριον. ὁ δὲ ἀπώμοσε μηδὲ ὀβολόν. Ἀλλὰ γῆν πολλὴν κέκτησαι; Ἴσως ἄν, ἔφη, Αὐτολύκωι τούτωι ἱκανὴ γένοιτο ἐγκονίσασθαι.", "st": "3.8"}, {"sp": "N", "t": "Ἀκουστέον ἂν εἴη καὶ σοῦ. τί γὰρ σύ, ἔφη, ὦ Χαρμίδη, ἐπὶ τίνι μέγα φρονεῖς; Ἐγὼ αὖ, ἔφη, ἐπὶ πενίαι μέγα φρονῶ. Νὴ Δί᾽, ἔφη ὁ Σωκράτης, ἐπ᾽ εὐχαρίτωι γε πράγματι. τοῦτο γὰρ δὴ ἥκιστα μὲν ἐπίφθονον, ἥκιστα δὲ περιμάχητον, καὶ ἀφύλακτον ὂν σώιζεται καὶ ἀμελούμενον ἰσχυρότερον γίγνεται.", "st": "3.9"}, {"sp": "N", "t": "Σὺ δὲ δή, ἔφη ὁ Καλλίας, ἐπὶ τίνι μέγα φρονεῖς, ὦ Σώκρατες; καὶ ὃς μάλα σεμνῶς ἀνασπάσας τὸ πρόσωπον, Ἐπὶ μαστροπείαι, εἶπεν. ἐπεὶ δὲ ἐγέλασαν ἐπ᾽ αὐτῶι, Ὑμεῖς μὲν γελᾶτε, ἔφη, ἐγὼ δὲ οἶδ᾽ ὅτι καὶ πάνυ ἂν πολλὰ χρήματα λαμβάνοιμι, εἰ βουλοίμην χρῆσθαι τῆι τέχνηι.", "st": "3.10"}, {"sp": "N", "t": "Σύ γε μὴν δῆλον, ἔφη ὁ Λύκων τὸν Φίλιππον ⟨προσειπών, ὅτι⟩ ἐπὶ τῶι γελωτοποιεῖν μέγα φρονεῖς. Δικαιότερόν γ᾽, ἔφη, οἴομαι, ἢ Καλλιππίδης ὁ ὑποκριτής, ὃς ὑπερσεμνύνεται ὅτι δύναται πολλοὺς κλαίοντας καθίζειν.", "st": "3.11"}, {"sp": "N", "t": "Οὐκοῦν καὶ σύ, ἔφη ὁ Ἀντισθένης, λέξεις, ὦ Λύκων, ἐπὶ τίνι μέγα φρονεῖς; καὶ ὃς ἔφη· Οὐ γὰρ ἅπαντες ἴστε, ἔφη, ⟨ὅτι⟩ ἐπὶ τούτωι τῶι υἱεῖ; Οὗτός γε μήν, ἔφη τις, δῆλον ὅτι ἐπὶ τῶι νικηφόρος εἶναι. καὶ ὁ Αὐτόλυκος ἀνερυθριάσας εἶπε· Μὰ Δί᾽, οὐκ ἔγωγε.", "st": "3.12"}, {"sp": "N", "t": "ἐπεὶ δὲ ἅπαντες ἡσθέντες ὅτι ἤκουσαν αὐτοῦ φωνήσαντος προσέβλεψαν, ἤρετό τις αὐτόν· Ἀλλ᾽ ἐπὶ τῶι μήν, ὦ Αὐτόλυκε; ὁ δ᾽ εἶπεν· ἐπὶ τῶι πατρί, καὶ ἅμα ἐνεκλίθη αὐτῶι. καὶ ὁ Καλλίας ἰδών, Ἆρ᾽ οἶσθα, ἔφη, ὦ Λύκων, ὅτι πλουσιώτατος εἶ ἀνθρώπων; Μὰ Δί᾽, ἔφη, τοῦτο μέντοι ἐγὼ οὐκ οἶδα. Ἀλλὰ λανθάνει σε ὅτι οὐκ ἂν δέξαιο τὰ βασιλέως χρήματα ἀντὶ τοῦ υἱοῦ; Ἐπ᾽ αὐτοφώρωι εἴλημμαι, ἔφη, πλουσιώτατος, ὡς ἔοικεν, ἀνθρώπων ὤν. Σὺ δέ, ἔφη ὁ Νικήρατος, ὦ Ἑρμόγενες, ἐπὶ τίνι μάλιστα", "st": "3.13"}, {"sp": "N", "t": "ἀγάλληι; καὶ ὃς, Ἐπὶ φίλων, ἔφη, ἀρετῆι καὶ δυνάμει, καὶ ὅτι τοιοῦτοι ὄντες ἐμοῦ ἐπιμέλονται. ἐνταῦθα τοίνυν πάντες προσέβλεψαν αὐτῶι, καὶ πολλοὶ ἅμα ἤροντο εἰ καὶ σφίσι δηλώσοι αὐτούς. ὁ δὲ εἶπεν ὅτι οὐ φθονήσει.", "st": "3.14"}, {"sp": "N", "t": "Ἐκ τούτου ἔλεξεν ὁ Σωκράτης· Οὐκοῦν λοιπὸν ἂν εἴη ἡμῖν ἃ ἕκαστος ὑπέσχετο ἀποδεικνύναι ὡς πολλοῦ ἄξιά ἐστιν. Ἀκούοιτ᾽ ἄν, ἔφη ὁ Καλλίας, ἐμοῦ πρῶτον. ἐγὼ γὰρ ἐν τῶι χρόνωι ὧι ὑμῶν ἀκούω ἀπορούντων τί τὸ δίκαιον, ἐν τούτωι δικαιοτέρους τοὺς ἀνθρώπους ποιῶ. καὶ ὁ Σωκράτης, Πῶς, ὦ λῶιστε; ἔφη. Διδοὺς νὴ Δί᾽ ἀργύριον.", "st": "4.1"}, {"sp": "N", "t": "καὶ ὁ Ἀντισθένης ἐπαναστὰς μάλα ἐλεγκτικῶς αὐτὸν ἐπήρετο· Οἱ δὲ ἄνθρωποι, ὦ Καλλία, πότερον ἐν ταῖς ψυχαῖς ἢ ἐν τῶι βαλαντίωι τὸ δίκαιόν σοι δοκοῦσιν ἔχειν; Ἐν ταῖς ψυχαῖς, ἔφη. Κἄπειτα σὺ εἰς τὸ βαλάντιον διδοὺς ἀργύριον τὰς ψυχὰς δικαιοτέρους ποιεῖς; Μάλιστα. Πῶς; Ὅτι διὰ τὸ εἰδέναι ὡς ἔστιν ὅτου πριάμενοι τὰ ἐπιτήδεια ἕξουσιν οὐκ ἐθέλουσι κακουργοῦντες κινδυνεύειν.", "st": "4.2"}, {"sp": "N", "t": "Ἦ καί σοι, ἔφη, ἀποδιδόασιν ὅ τι ἂν λάβωσι; Μὰ τὸν Δί᾽, ἔφη, οὐ μὲν δή. Τί δέ, ἀντὶ τοῦ ἀργυρίου χάριτας; Οὐ μὰ τὸν Δί᾽, ἔφη, οὐδὲ τοῦτο, ἀλλ᾽ ἔνιοι καὶ ἐχθιόνως ἔχουσιν ἢ πρὶν λαβεῖν. Θαυμαστά γ᾽, ἔφη ὁ Ἀντισθένης ἅμα εἰσβλέπων ὡς ἐλέγχων αὐτόν, εἰ πρὸς μὲν τοὺς ἄλλους δύνασαι δικαίους ποιεῖν αὐτούς, πρὸς δὲ σαυτὸν οὔ.", "st": "4.3"}, {"sp": "N", "t": "Καὶ τί τοῦτ᾽, ἔφη ὁ Καλλίας, θαυμαστόν; οὐ καὶ τέκτονάς τε καὶ οἰκοδόμους πολλοὺς ὁρᾶις οἳ ἄλλοις μὲν πολλοῖς ποιοῦσιν οἰκίας, ἑαυτοῖς δὲ οὐ δύνανται ποιῆσαι, ἀλλ᾽ ἐν μισθωταῖς οἰκοῦσι; καὶ ἀνάσχου μέντοι, ὦ σοφιστά, ἐλεγχόμενος.", "st": "4.4"}, {"sp": "N", "t": "Νὴ Δί᾽, ἔφη ὁ Σωκράτης, ἀνεχέσθω μέντοι· ἐπεὶ καὶ οἱ μάντεις λέγονται δὴπου ἄλλοις μὲν προαγορεύειν τὸ μέλλον, ἑαυτοῖς δὲ μὴ προορᾶν τὸ ἐπιόν.", "st": "4.5"}, {"sp": "N", "t": "οὗτος μὲν δὴ ὁ λόγος ἐνταῦθα ἔληξεν. ἐκ τούτου δὲ ὁ Νικήρατος, Ἀκούοιτ᾽ ἄν, ἔφη, καὶ ἐμοῦ ἃ ἔσεσθε βελτίονες, ἂν ἐμοὶ συνῆτε. ἴστε γὰρ δήπου ὅτι Ὅμηρος ὁ σοφώτατος πεποίηκε σχεδὸν περὶ πάντων τῶν ἀνθρωπίνων. ὅστις ἂν οὖν ὑμῶν βούληται ἢ οἰκονομικὸς ἢ δημηγορικὸς ἢ στρατηγικὸς γενέσθαι ἢ ὅμοιος Ἀχιλλεῖ ἢ Αἴαντι ἢ Νέστορι ἢ Ὀδυσσεῖ, ἐμὲ θεραπευέτω. ἐγὼ γὰρ ταῦτα πάντα ἐπίσταμαι. Ἦ καὶ βασιλεύειν, ἔφη ὁ Ἀντισθένης, ἐπίστασαι, ὅτι οἶσθα ἐπαινέσαντα αὐτὸν τὸν Ἀγαμέμνονα ὡς βασιλεύς τε εἴη ἀγαθὸς κρατερός τ᾽ αἰχμητής; Καὶ ναὶ μὰ Δί᾽, ἔφη, ἔγωγε ὅτι ἁρματηλατοῦντα δεῖ ἐγγὺς μὲν τῆς στήλης κάμψαι, αὐτὸν δὲ κλινθῆναι ἐυξέστου ἐπὶ δίφρου ἦκ᾽ ἐπ᾽ ἀριστερὰ τοῖιν, ἀτὰρ τὸν δεξιὸν ἵππον κένσαι ὁμοκλήσαντ᾽ εἶξαί τέ οἱ ἡνία χερσί.", "st": "4.6"}, {"sp": "N", "t": "καὶ πρὸς τούτοις γε ἄλλο οἶδα, καὶ ὑμῖν αὐτίκα μάλ᾽ ἔξεστι πειρᾶσθαι. εἶπε γάρ που Ὅμηρος· Ἐπὶ δὲ κρόμυον ποτῶι ὄψον. ἐὰν οὖν ἐνέγκηι τις κρόμμυον, αὐτίκα μάλα τοῦτό γε ὠφελημένοι ἔσεσθε· ἥδιον γὰρ πιεῖσθε.", "st": "4.7"}, {"sp": "N", "t": "καὶ ὁ Χαρμίδης εἶπεν· Ὦ ἄνδρες, ὁ Νικήρατος κρομμύων ὄζων ἐπιθυμεῖ οἴκαδε ἐλθεῖν, ἵν᾽ ἡ γυνὴ αὐτοῦ πιστεύηι μηδὲ διανοηθῆναι μηδένα ἂν φιλῆσαι αὐτόν. Νὴ Δί᾽, ἔφη ὁ Σωκράτης, ἀλλ᾽ ἄλλην που δόξαν γελοίαν κίνδυνος ἡμῖν προσλαβεῖν. ὄψον μὲν γὰρ δὴ ὄντως ἔοικεν εἶναι, ὡς κρόμμυόν γε οὐ μόνον σῖτον ἀλλὰ καὶ ποτὸν ἡδύνει. εἰ δὲ δὴ τοῦτο καὶ μετὰ δεῖπνον τρωξόμεθα, ὅπως μὴ φήσηι τις ἡμᾶς πρὸς Καλλίαν ἐλθόντας ἡδυπαθεῖν.", "st": "4.8"}, {"sp": "N", "t": "Μηδαμῶς, ἔφη, ὦ Σώκρατες. εἰς μὲν γὰρ μάχην ὁρμωμένωι καλῶς ἔχει κρόμμυον ὑποτρώγειν, ὥσπερ ἔνιοι τοὺς ἀλεκτρυόνας σκόροδα σιτίσαντες συμβάλλουσιν· ἡμεῖς δὲ ἴσως βουλευόμεθα ὅπως φιλήσομέν τινα μᾶλλον ἢ μαχούμεθα.", "st": "4.9"}, {"sp": "N", "t": "καὶ οὗτος μὲν δὴ ὁ λόγος οὕτω πως ἐπαύσατο. ὁ δὲ Κριτόβουλος, Οὐκοῦν αὖ ἐγὼ λέξω, ἔφη, ἐξ ὧν ἐπὶ τῶι κάλλει μέγα φρονῶ. Λέγε, ἔφασαν. Εἰ μὲν τοίνυν μὴ καλός εἰμι, ὡς οἴομαι, ὑμεῖς ἂν δικαίως ἀπάτης δίκην ὑπέχοιτε· οὐδενὸς γὰρ ὁρκίζοντος ἀεὶ ὀμνύοντες καλόν μέ φατε εἶναι. κἀγὼ μέντοι πιστεύω. καλοὺς γὰρ καὶ ἀγαθοὺς ὑμᾶς ἄνδρας νομίζω.", "st": "4.10"}, {"sp": "N", "t": "εἰ δ᾽ εἰμί τε τῶι ὄντι καλὸς καὶ ὑμεῖς τὰ αὐτὰ πρὸς ἐμὲ πάσχετε οἷάπερ ἐγὼ πρὸς τὸν ἐμοὶ δοκοῦντα καλὸν εἶναι, ὄμνυμι πάντας θεοὺς μὴ ἑλέσθαι ἂν τὴν βασιλέως ἀρχὴν ἀντὶ τοῦ καλὸς εἶναι.", "st": "4.11"}, {"sp": "N", "t": "νῦν γὰρ ἐγὼ Κλεινίαν ἥδιον μὲν θεῶμαι ἢ τἆλλα πάντα τὰ ἐν ἀνθρώποις καλά. τυφλὸς δὲ τῶν ἄλλων ἁπάντων μᾶλλον δεξαίμην ἂν εἶναι ἢ Κλεινίου ἑνὸς ὄντος· ἄχθομαι δὲ καὶ νυκτὶ καὶ ὕπνωι ὅτι ἐκεῖνον οὐχ ὁρῶ, ἡμέραι δὲ καὶ ἡλίωι τὴν μεγίστην χάριν οἶδα ὅτι μοι Κλεινίαν ἀναφαίνουσιν.", "st": "4.12"}, {"sp": "N", "t": "ἄξιόν γε μὴν ἡμῖν τοῖς καλοῖς καὶ ἐπὶ τοῖσδε μέγα φρονεῖν, ὅτι τὸν μὲν ἰσχυρὸν πονοῦντα δεῖ κτᾶσθαι τἀγαθὰ καὶ τὸν ἀνδρεῖον κινδυνεύοντα, τὸν δέ γε σοφὸν λέγοντα· ὁ δὲ καλὸς καὶ ἡσυχίαν ἔχων πάντ᾽ ἂν διαπράξαιτο.", "st": "4.13"}, {"sp": "N", "t": "ἐγὼ γοῦν καίπερ εἰδὼς ὅτι χρήματα ἡδὺ κτῆμα ἥδιον μὲν ἂν Κλεινίαι τὰ ὄντα διδοίην ἢ ἕτερα παρ᾽ ἄλλου λαμβάνοιμι, ἥδιον δ᾽ ἂν δουλεύοιμι ἢ ἐλεύθερος εἴην, εἴ μου Κλεινίας ἄρχειν ἐθέλοι. καὶ γὰρ πονοίην ἂν ῥᾶιον ἐκείνωι ἢ ἀναπαυοίμην, καὶ κινδυνεύοιμ᾽ ἂν πρὸ ἐκείνου ἥδιον ἢ ἀκίνδυνος ζώιην.", "st": "4.14"}, {"sp": "N", "t": "ὥστε εἰ σύ, ὦ Καλλία, μέγα φρονεῖς ὅτι δικαιοτέρους δύνασαι ποιεῖν, ἐγὼ πρὸς πᾶσαν ἀρετὴν δικαιότερος σοῦ εἰμι ἄγων ἀνθρώπους. διὰ γὰρ τὸ ἐμπνεῖν τι ἡμᾶς τοὺς καλοὺς τοῖς ἐρωτικοῖς ἐλευθεριωτέρους μὲν αὐτοὺς ποιοῦμεν εἰς χρήματα, φιλοπονωτέρους δὲ καὶ φιλοκαλωτέρους ἐν τοῖς κινδύνοις, καὶ μὴν αἰδημονεστέρους τε καὶ ἐγκρατεστέρους, οἵ γε καὶ ὧν δέονται μάλιστα ταῦτ᾽ αἰσχύνονται.", "st": "4.15"}, {"sp": "N", "t": "μαίνονται δὲ καὶ οἱ μὴ τοὺς καλοὺς στρατηγοὺς αἱρούμενοι. ἐγὼ γοῦν μετὰ Κλεινίου κἂν διὰ πυρὸς ἰοίην· οἶδα δ᾽ ὅτι καὶ ὑμεῖς μετ᾽ ἐμοῦ. ὥστε μηκέτι ἀπόρει, ὦ Σώκρατες, εἴ τι τοὐμὸν κάλλος ἀνθρώπους ὠφελήσει.", "st": "4.16"}, {"sp": "N", "t": "ἀλλ᾽ οὐδὲ μέντοι ταύτηι γε ἀτιμαστέον τὸ κάλλος ὡς ταχὺ παρακμάζον, ἐπεὶ ὥσπερ γε παῖς γίγνεται καλός, οὕτω καὶ μειράκιον καὶ ἀνὴρ καὶ πρεσβύτης. τεκμήριον δέ· θαλλοφόρους γὰρ τῆι Ἀθηνᾶι τοὺς καλοὺς γέροντας ἐκλέγονται, ὡς συμπαρομαρτοῦντος πάσηι ἡλικίαι τοῦ κάλλους.", "st": "4.17"}, {"sp": "N", "t": "εἰ δὲ ἡδὺ τὸ παρ᾽ ἑκόντων διαπράττεσθαι ὧν τις δέοιτο, εὖ οἶδ᾽ ὅτι καὶ νυνὶ θᾶττον ἂν ἐγὼ καὶ σιωπῶν πείσαιμι τὸν παῖδα τόνδε καὶ τὴν παῖδα φιλῆσαί με ἢ σύ, ὦ Σώκρατες, εἰ καὶ πάνυ πολλὰ καὶ σοφὰ λέγοις.", "st": "4.18"}, {"sp": "N", "t": "Τί τοῦτο; ἔφη ὁ Σωκράτης· ὡς γὰρ καὶ ἐμοῦ καλλίων ὢν ταῦτα κομπάζεις. Νὴ Δί᾽, ἔφη ὁ Κριτόβουλος, ἢ πάντων Σειληνῶν τῶν ἐν τοῖς σατυρικοῖς αἴσχιστος ἂν εἴην. [ὁ δὲ Σωκράτης καὶ ἐτύγχανε προσεμφερὴς τούτοις ὤν.]", "st": "4.19"}, {"sp": "N", "t": "Ἄγε νυν, ἔφη ὁ Σωκράτης, ὅπως μεμνήσηι διακριθῆναι περὶ τοῦ κάλλους, ἐπειδὰν οἱ προκείμενοι λόγοι περιέλθωσι. κρινάτω δ᾽ ἡμᾶς μὴ Ἀλέξανδρος ὁ Πριάμου, ἀλλ᾽ αὐτοὶ οὗτοι οὕσπερ σὺ οἴει ἐπιθυμεῖν σε φιλῆσαι.", "st": "4.20"}, {"sp": "N", "t": "Κλεινίαι δ᾽, ἔφη, ὦ Σώκρατες, οὐκ ἂν ἐπιτρέψαις; καὶ ὃς εἶπεν· Οὐ γὰρ παύσηι σὺ Κλεινίου μεμνημένος; Ἂν δὲ μὴ ὀνομάζω, ἧττόν τί με οἴει μεμνῆσθαι αὐτοῦ; οὐκ οἶσθα ὅτι οὕτω σαφὲς ἔχω εἴδωλον αὐτοῦ ἐν τῆι ψυχῆι ὡς εἰ πλαστικὸς ἢ ζωγραφικὸς ἦν, οὐδὲν ἂν ἧττον ἐκ τοῦ εἰδώλου ἢ πρὸς αὐτὸν ὁρῶν ὅμοιον αὐτῶι ἀπειργασάμην;", "st": "4.21"}, {"sp": "N", "t": "καὶ ὁ Σωκράτης ὑπέλαβε· Τί δῆτα οὕτως ὅμοιον εἴδωλον ἔχων πράγματά μοι παρέχεις ἄγεις τε αὐτὸν ὅπου ὄψει; Ὅτι, ὦ Σώκρατες, ἡ μὲν αὐτοῦ ὄψις εὐφραίνειν δύναται, ἡ δὲ τοῦ εἰδώλου τέρψιν μὲν οὐ παρέχει, πόθον δὲ ἐμποιεῖ.", "st": "4.22"}, {"sp": "N", "t": "καὶ ὁ Ἑρμογένης εἶπεν· Ἀλλ᾽ ἐγώ, ὦ Σώκρατες, οὐδὲ πρὸς σοῦ ποιῶ τὸ περιιδεῖν Κριτόβουλον οὕτως ὑπὸ τοῦ ἔρωτος ἐκπλαγέντα. Δοκεῖς γάρ, ἔφη ὁ Σωκράτης, ἐξ οὗ ἐμοὶ σύνεστιν οὕτω διατεθῆναι αὐτόν; Ἀλλὰ πότε μήν; Οὐχ ὁρᾶις ὅτι τούτωι μὲν παρὰ τὰ ὦτα ἄρτι ἴουλος καθέρπει, Κλεινίαι δὲ πρὸς τὸ ὄπισθεν ἤδη ἀναβαίνει; οὗτος οὖν συμφοιτῶν εἰς ταὐτὸ διδασκαλεῖον ἐκείνωι τότε ἰσχυρῶς προσεκαύθη.", "st": "4.23"}, {"sp": "N", "t": "ἃ δὴ αἰσθόμενος ὁ πατὴρ παρέδωκέ μοι αὐτόν, εἴ τι δυναίμην ὠφελῆσαι. καὶ μέντοι πολὺ βέλτιον ἤδη ἔχει. πρόσθεν μὲν γάρ, ὥσπερ οἱ τὰς Γοργόνας θεώμενοι, λιθίνως ἔβλεπε πρὸς αὐτὸν καὶ οὐδαμοῦ ἀπήιει ἀπ᾽ αὐτοῦ· νῦν δὲ ἤδη εἶδον αὐτὸν καὶ σκαρδαμύξαντα.", "st": "4.24"}, {"sp": "N", "t": "καίτοι νὴ τοὺς θεούς, ὦ ἄνδρες, δοκεῖ μοί γ᾽, ἔφη, ὡς ἐν ἡμῖν αὐτοῖς εἰρῆσθαι, οὗτος καὶ πεφιληκέναι τὸν Κλεινίαν· οὗ ἔρωτος οὐδέν ἐστι δεινότερον ὑπέκκαυμα. καὶ γὰρ ἄπληστον καὶ ἐλπίδας τινὰς γλυκείας παρέχει.", "st": "4.25"}, {"sp": "N", "t": "[ἴσως δὲ καὶ διὰ τὸ μόνον πάντων ἔργων τὸ τοῖς σ⟨τό⟩μασι συμψαύειν ὁμώνυμον εἶναι τῶι ταῖς ψυχαῖς φιλεῖσθαι ἐντιμότερόν ἐστιν.] οὗ ἕνεκα ἀφεκτέον ἐγώ φημι εἶναι φιλημάτων ⟨τῶν⟩ ὡραίων τῶι σωφρονεῖν δυνησομένωι.", "st": "4.26"}, {"sp": "N", "t": "καὶ ὁ Χαρμίδης εἶπεν· Ἀλλὰ τί δή ποτε, ὦ Σώκρατες, ἡμᾶς μὲν οὕτω τοὺς φίλους μορμολύττηι ἀπὸ τῶν καλῶν, αὐτὸν δέ σε, ἔφη, ἐγὼ εἶδον ναὶ μὰ τὸν Ἀπόλλω, ὅτε παρὰ τῶι γραμματιστῆι ἐν τῶι αὐτῶι βιβλίωι ἀμφότεροι ἐμαστεύετέ τι, τὴν κεφαλὴν πρὸς τῆι κεφαλῆι καὶ τὸν ὦμον γυμνὸν πρὸς γυμνῶι τῶι Κριτοβούλου ὤμωι ἔχοντα.", "st": "4.27"}, {"sp": "N", "t": "καὶ ὀ Σωκράτης, Φεῦ, ἔφη, ταῦτ᾽ ἄρα ἐγὼ ὥσπερ ὑπὸ θηρίου τινὸς δεδηγμένος τόν τε ὦμον πλεῖν ἢ πέντε ἡμέρας ὤδαξον καὶ ἐν τῆι καρδίαι ὥσπερ κνῆσμά τι ἐδόκουν ἔχειν. ἀλλὰ νῦν τοί σοι, ἔφη, ὦ Κριτόβουλε, ἐναντίον τοσούτων μαρτύρων προαγορεύω μὴ ἅπτεσθαί μου πρὶν ἂν τὸ γένειον τῆι κεφαλῆι ὁμοίως κομήσηις. Καὶ οὗτοι μὲν δὴ οὕτως ἀναμὶξ ἔσκωψάν τε καὶ ἐσπούδασαν.", "st": "4.28"}, {"sp": "N", "t": "ὁ δὲ Καλλίας, Σὸν μέρος, ἔφη, λέγειν, ὦ Χαρμίδη, δι᾽ ὅ τι ἐπὶ πενίαι μέγα φρονεῖς. Οὐκοῦν τόδε μέν, ἔφη, ὁμολογεῖται, κρεῖττον εἶναι θαρρεῖν ἢ φοβεῖσθαι καὶ ἐλεύθερον εἶναι μᾶλλον ἢ δουλεύειν καὶ θεραπεύεσθαι μᾶλλον ἢ θεραπεύειν καὶ πιστεύεσθαι ὑπὸ τῆς πατρίδος μᾶλλον ἢ ἀπιστεῖσθαι.", "st": "4.29"}, {"sp": "N", "t": "ἐγὼ τοίνυν ἐν τῆιδε τῆι πόλει ὅτε μὲν πλούσιος ἦν πρῶτον μὲν ἐφοβούμην μή τίς μου τὴν οἰκίαν διορύξας καὶ τὰ χρήματα λάβοι καὶ αὐτόν τί με κακὸν ἐργάσαιτο· ἔπειτα δὲ καὶ τοὺς συκοφάντας ἐθεράπευον, εἰδὼς ὅτι παθεῖν μᾶλλον κακῶς ἱκανὸς εἴην ἢ ποιῆσαι ἐκείνους. καὶ γὰρ δὴ καὶ προσετάττετο μὲν ἀεί τί μοι δαπανᾶν ὑπὸ τῆς πόλεως, ἀποδημῆσαι δὲ οὐδαμοῦ ἐξῆν.", "st": "4.30"}, {"sp": "N", "t": "νῦν δ᾽ ἐπειδὴ τῶν ὑπερορίων στέρομαι καὶ τὰ ἔγγεια οὐ καρποῦμαι καὶ τὰ ἐκ τῆς οἰκίας πέπραται, ἡδέως μὲν καθεύδω ἐκτεταμένος, πιστὸς δὲ τῆι πόλει γεγένημαι, οὐκέτι δὲ ἀπειλοῦμαι, ἀλλ᾽ ἤδη ἀπειλῶ ἄλλοις, ὡς ἐλευθέρωι τε ἔξεστί μοι καὶ ἀποδημεῖν καὶ ἐπιδημεῖν· ὑπανίστανται δέ μοι ἤδη καὶ θάκων καὶ ὁδῶν ἐξίστανται οἱ πλούσιοι.", "st": "4.31"}, {"sp": "N", "t": "καὶ εἰμὶ νῦν μὲν τυράννωι ἐοικώς, τότε δὲ σαφῶς δοῦλος ἦν· καὶ τότε μὲν ἐγὼ φόρον ἀπέφερον τῶι δήμωι, νῦν δὲ ἡ πόλις τέλος φέρουσα τρέφει με. ἀλλὰ καὶ Σωκράτει, ὅτε μὲν πλούσιος ἦν, ἐλοιδόρουν με ὅτι συνῆν, νῦν δ᾽ ἐπεὶ πένης γεγένημαι, οὐκέτι οὐδὲν μέλει οὐδενί. καὶ μὴν ὅτε μέν γε πολλὰ εἶχον, ἀεί τι ἀπέβαλλον ἢ ὑπὸ τῆς πόλεως ἢ ὑπὸ τῆς τύχης· νῦν δὲ ἀποβάλλω μὲν οὐδέν (οὐδὲ γὰρ ἔχω), ἀεὶ δέ τι λήψεσθαι ἐλπίζω.", "st": "4.32"}, {"sp": "N", "t": "Οὐκοῦν, ἔφη ὁ Καλλίας, καὶ εὔχηι μηδέποτε πλουτεῖν, καὶ ἐάν τι ὄναρ ἀγαθὸν ἴδηις, τοῖς ἀποτροπαίοις θύεις; Μὰ Δία τοῦτο μέντοι, ἔφη, ἐγὼ οὐ ποιῶ, ἀλλὰ μάλα φιλοκινδύνως ὑπομένω, ἄν ποθέν τι ἐλπίζω λήψεσθαι.", "st": "4.33"}, {"sp": "N", "t": "Ἀλλ᾽ ἄγε δή, ἔφη ὁ Σωκράτης, σὺ αὖ λέγε ἡμῖν, ὦ Ἀντίσθενες, πῶς οὕτω βραχέα ἔχων μέγα φρονεῖς ἐπὶ πλούτωι. Ὅτι νομίζω, ὦ ἄνδρες, τοὺς ἀνθρώπους οὐκ ἐν τῶι οἴκωι τὸν πλοῦτον καὶ τὴν πενίαν ἔχειν ἀλλ᾽ ἐν ταῖς ψυχαῖς.", "st": "4.34"}, {"sp": "N", "t": "ὁρῶ γὰρ πολλοὺς μὲν ἰδιώτας, οἳ πάνυ πολλὰ ἔχοντες χρήματα οὕτω πένεσθαι ἡγοῦνται ὥστε πάντα μὲν πόνον, πάντα δὲ κίνδυνον ὑποδύονται, ἐφ᾽ ὧι πλείω κτήσονται, οἶδα δὲ καὶ ἀδελφούς, οἳ τὰ ἴσα λαχόντες ὁ μὲν αὐτῶν τἀρκοῦντα ἔχει καὶ περιττεύοντα τῆς δαπάνης, ὁ δὲ τοῦ παντὸς ἐνδεῖται·", "st": "4.35"}, {"sp": "N", "t": "αἰσθάνομαι δὲ καὶ τυράννους τινάς, οἳ οὕτω πεινῶσι χρημάτων ὥστε ποιοῦσι πολὺ δεινότερα τῶν ἀπορωτάτων· δι᾽ ἔνδειαν μὲν γὰρ δήπου οἱ μὲν κλέπτουσιν, οἱ δὲ τοιχωρυχοῦσιν, οἱ δὲ ἀνδραποδίζονται· τύραννοι δ᾽ εἰσί τινες οἳ ὅλους μὲν οἴκους ἀναιροῦσιν, ἁθρόους δ᾽ ἀποκτείνουσι, πολλάκις δὲ καὶ ὅλας πόλεις χρημάτων ἕνεκα ἐξανδραποδίζονται.", "st": "4.36"}, {"sp": "N", "t": "τούτους μὲν οὖν ἕγωγε καὶ πάνυ οἰκτίρω τῆς ἄγαν χαλεπῆς νόσου. ὅμοια γάρ μοι δοκοῦσι πάσχειν ὥσπερ εἴ τις πολλὰ ἔχοι καὶ πολλὰ ἐσθίων μηδέποτε ἐμπίμπλαιτο. ἐγὼ δὲ οὕτω μὲν πολλὰ ἔχω ὡς μόλις αὐτὰ καὶ αὐτὸς εὑρίσκω· ὅμως δὲ περίεστί μοι καὶ ἐσθίοντι ἄχρι τοῦ μὴ πεινῆν ἀφικέσθαι καὶ πίνοντι μέχρι τοῦ μὴ διψῆν καὶ ἀμφιέννυσθαι ὥστε ἔξω μὲν μηδὲν μᾶλλον Καλλίου τούτου τοῦ πλουσιωτάτου ῥιγοῦν·", "st": "4.37"}, {"sp": "N", "t": "ἐπειδάν γε μὴν ἐν τῆι οἰκίαι γένωμαι, πάνυ μὲν ἀλεεινοὶ χιτῶνες οἱ τοῖχοί μοι δοκοῦσιν εἶναι, πάνυ δὲ παχεῖαι ἐφεστρίδες οἱ ὄροφοι, στρωμνήν γε μὴν οὕτως ἀρκοῦσαν ἔχω ὥστ᾽ ἔργον μέγ᾽ ἐστὶ καὶ ἀνεγεῖραι. ἂν δέ ποτε καὶ ἀφροδισιάσαι τὸ σῶμά μου δεηθῆι, οὕτω μοι τὸ παρὸν ἀρκεῖ ὥστε αἷς ἂν προσέλθω ὑπερασπάζονταί με διὰ τὸ μηδένα ἄλλον αὐταῖς ἐθέλειν προσιέναι.", "st": "4.38"}, {"sp": "N", "t": "καὶ πάντα τοίνυν ταῦτα οὕτως ἡδέα μοι δοκεῖ εἶναι ὡς μᾶλλον μὲν ἥδεσθαι ποιῶν ἕκαστα αὐτῶν οὐκ ἂν εὐξαίμην, ἧττον δέ· οὕτω μοι δοκεῖ ἔνια αὐτῶν ἡδίω εἶναι τοῦ συμφέροντος.", "st": "4.39"}, {"sp": "N", "t": "πλείστου δ᾽ ἄξιον κτῆμα ἐν τῶι ἐμῶι πλούτωι λογίζομαι εἶναι ἐκεῖνο, ὅτι εἴ μού τις καὶ τὰ νῦν ὄντα παρέλοιτο, οὐδὲν οὕτως ὁρῶ φαῦλον ἔργον ὁποῖον οὐκ ἀρκοῦσαν ἂν τροφὴν ἐμοὶ παρέχοι.", "st": "4.40"}, {"sp": "N", "t": "καὶ γὰρ ὅταν ἡδυπαθῆσαι βουληθῶ, οὐκ ἐκ τῆς ἀγορᾶς τὰ τίμια ὠνοῦμαι (πολυτελῆ γὰρ γίγνεται), ἀλλ᾽ ἐκ τῆς ψυχῆς ταμιεύομαι. καὶ πολὺ πλέον διαφέρει πρὸς ἡδονήν, ὅταν ἀναμείνας τὸ δεηθῆναι προσφέρωμαι ἢ ὅταν τινὶ τῶν τιμίων χρῶμαι, ὥσπερ καὶ νῦν τῶιδε τῶι Θασίωι οἴνωι ἐντυχὼν οὐ διψῶν πίνω αὐτόν.", "st": "4.41"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ πολὺ δικαιοτέρους γε εἰκὸς εἶναι τοὺς εὐτέλειαν μᾶλλον ἢ πολυχρηματίαν σκοποῦντας. οἷς γὰρ μάλιστα τὰ παρόντα ἀρκεῖ ἥκιστα τῶν ἀλλοτρίων ὀρέγονται.", "st": "4.42"}, {"sp": "N", "t": "ἄξιον δ᾽ ἐννοῆσαι ὡς καὶ ἐλευθερίους ὁ τοιοῦτος πλοῦτος παρέχεται. Σωκράτης τε γὰρ οὗτος παρ᾽ οὗ ἐγὼ τοῦτον ἐκτησάμην οὔτ᾽ ἀριθμῶι οὔτε σταθμῶι ἐπήρκει μοι, ἀλλ᾽ ὁπόσον ἐδυνάμην φέρεσθαι, τοσοῦτόν μοι παρεδίδου· ἐγώ τε νῦν οὐδενὶ φθονῶ, ἀλλὰ πᾶσι τοῖς φίλοις καὶ ἐπιδεικνύω τὴν ἀφθονίαν καὶ μεταδίδωμι τῶι βουλομένωι τοῦ ἐν τῆι ἐμῆι ψυχῆι πλούτου.", "st": "4.43"}, {"sp": "N", "t": "καὶ μὴν καὶ τὸ ἁβρότατόν γε κτῆμα, τὴν σχολὴν ἀεὶ ὁρᾶτέ μοι παροῦσαν, ὥστε καὶ θεᾶσθαι τὰ ἀξιοθέατα καὶ ἀκούειν τὰ ἀξιάκουστα καὶ ὃ πλείστου ἐγὼ τιμῶμαι, Σωκράτει σχολάζων συνδιημερεύειν. καὶ οὗτος δὲ οὐ τοὺς πλεῖστον ἀριθμοῦντας χρυσίον θαυμάζει, ἀλλ᾽ οἳ ἂν αὐτῶι ἀρέσκωσι τούτοις συνὼν διατελεῖ. οὗτος μὲν οὖν οὕτως εἶπεν.", "st": "4.44"}, {"sp": "N", "t": "ὁ δὲ Καλλίας, Νὴ τὴν Ἥραν, ἔφη, τά τε ἄλλα ζηλῶ σε τοῦ πλούτου καὶ ὅτι οὔτε ἡ πόλις σοι ἐπιτάττουσα ὡς δούλωι χρῆται οὔτε οἱ ἄνθρωποι, ἂν μὴ δανείσηις, ὀργίζονται. Ἀλλὰ μὰ Δί᾽, ἔφη ὁ Νικήρατος, μὴ ζήλου· ἐγὼ γὰρ ἥξω παρ᾽ αὐτοῦ δανεισάμενος τὸ μηδενὸς προσδεῖσθαι, οὕτω πεπαιδευμένος ὑπὸ Ὁμήρου ἀριθμεῖν ἕπτ᾽ ἀπύρους τρίποδας, δέκα δὲ χρυσοῖο τάλαντα, αἴθωνας δὲ λέβητας ἐείκοσι, δώδεκα δ᾽ ἵππους σταθμῶι καὶ ἀριθμῶι, ὡς πλείστου πλούτου ἐπιθυμῶν οὐ παύομαι· ἐξ ὧν ἴσως καὶ φιλοχρηματώτερός τισι δοκῶ εἶναι. ἔνθα δὴ ἀνεγέλασαν ἅπαντες, νομίζοντες τὰ ὄντα εἰρηκέναι αὐτόν.", "st": "4.45"}, {"sp": "N", "t": "ἐκ τούτου εἶπέ τις· Σὸν ἔργον, ὦ Ἑρμόγενες, λέγειν τε τοὺς φίλους οἵτινές εἰσι καὶ ἐπιδεικνύναι ὡς μέγα τε δύνανται καὶ σοῦ ἐπιμέλονται, ἵνα δοκῆις δικαίως ἐπ᾽ αὐτοῖς μέγα φρονεῖν.", "st": "4.46"}, {"sp": "N", "t": "Οὐκοῦν ὡς μὲν καὶ Ἕλληνες καὶ βάρβαροι τοὺς θεοὺς ἡγοῦνται πάντα εἰδέναι τά τε ὄντα καὶ τὰ μέλλοντα εὔδηλον. πᾶσαι γοῦν αἱ πόλεις καὶ πάντα τὰ ἔθνη διὰ μαντικῆς ἐπερωτῶσι τοὺς θεοὺς τί τε χρὴ καὶ τί οὐ χρὴ ποιεῖν. καὶ μὴν ὅτι νομίζομέν γε δύνασθαι αὐτοὺς καὶ εὖ καὶ κακῶς ποιεῖν καὶ τοῦτο σαφές. πάντες γοῦν αἰτοῦνται τοὺς θεοὺς τὰ μὲν φαῦλα ἀποτρέπειν, τἀγαθὰ δὲ διδόναι.", "st": "4.47"}, {"sp": "N", "t": "οὗτοι τοίνυν οἱ πάντα μὲν εἰδότες πάντα δὲ δυνάμενοι θεοὶ οὕτω μοι φίλοι εἰσὶν ὥστε διὰ τὸ ἐπιμελεῖσθαί μου οὔποτε λήθω αὐτοὺς οὔτε νυκτὸς οὔθ᾽ ἡμέρας οὔθ᾽ ὅποι ἂν ὁρμῶμαι οὔθ᾽ ὅ τι ἂν μέλλω πράττειν. διὰ δὲ τὸ προειδέναι καὶ ὅ τι ἐξ ἑκάστου ἀποβήσεται σημαίνουσί μοι πέμποντες ἀγγέλους φήμας καὶ ἐνύπνια καὶ οἰωνοὺς ἅ τε δεῖ καὶ ἃ οὐ χρὴ ποιεῖν, οἷς ἐγὼ ὅταν μὲν πείθωμαι, οὐδέποτέ μοι μεταμέλει· ἤδη δέ ποτε καὶ ἀπιστήσας ἐκολάσθην.", "st": "4.48"}, {"sp": "N", "t": "καὶ ὁ Σωκράτης εἶπεν· Ἀλλὰ τούτων μὲν οὐδὲν ἄπιστον. ἐκεῖνο μέντοι ἔγωγε ἡδέως ἂν πυθοίμην, πῶς αὐτοὺς θεραπεύων οὕτω φίλους ἔχεις. Ναὶ μὰ τὸν Δί᾽, ἔφη ὁ Ἑρμογένης, καὶ μάλα εὐτελῶς. ἐπαινῶ τε γὰρ αὐτοὺς οὐδὲν δαπανῶν, ὧν τε διδόασιν ἀεὶ αὖ παρέχομαι, εὐφημῶ τε ὅσα ἂν δύνωμαι καὶ ἐφ᾽ οἷς ἂν αὐτοὺς μάρτυρας ποιήσωμαι ἑκὼν οὐδὲν ψεύδομαι. Νὴ Δί᾽, ἔφη, ὁ Σωκράτης εἰ ἅρα τοιοῦτος ὢν φίλους αὐτοὺς ἔχεις, καὶ οἱ θεοί, ὡς ἔοικε, καλοκἀγαθίαι ἥδονται.", "st": "4.49"}, {"sp": "N", "t": "οὗτος μὲν δὴ ὁ λόγος οὕτως ἐσπουδαιολογήθη. ἐπειδὴ δὲ εἰς τὸν Φίλιππον ἧκον, ἠρώτων αὐτὸν τί ὁρῶν ἐν τῆι γελωτοποιίαι μέγα ἐπ᾽ αὐτῆι φρονοίη. Οὐ γὰρ ἄξιον, ἔφη, ὁπότε γε πάντες εἰδότες ὅτι γελωτοποιός εἰμι, ὅταν μέν τι ἀγαθὸν ἔχωσι, παρακαλοῦσί με ἐπὶ ταῦτα προθύμως, ὅταν δέ τι κακὸν λάβωσι, φεύγουσιν ἀμεταστρεπτί, φοβούμενοι μὴ καὶ ἄκοντες γελάσωσι;", "st": "4.50"}, {"sp": "N", "t": "καὶ ὁ Νικήρατος εἶπε· Νὴ Δία, σὺ τοίνυν δικαίως μέγα φρονεῖς. ἐμοὶ γὰρ αὖ τῶν φίλων οἱ μὲν εὖ πράττοντες ἐκποδὼν ἀπέρχονται, οἳ δ᾽ ἂν κακόν τι λάβωσι, γενεαλογοῦσι τὴν συγγένειαν καὶ οὐδέποτέ μου ἀπολείπονται.", "st": "4.51"}, {"sp": "N", "t": "Εἶεν· σὺ δὲ δή, ἔφη ὁ Χαρμίδης, ὦ Συρακόσιε, ἐπὶ τῶι μέγα φρονεῖς; ἢ δῆλον ὅτι ἑπὶ τῶι παιδί; Μὰ τὸν Δί᾽, ἔφη, οὐ μὲν δή· ἀλλὰ καὶ δέδοικα περὶ αὐτοῦ ἰσχυρῶς. αἰσθάνομαι γάρ τινας ἐπιβουλεύοντας διαφθεῖραι αὐτόν.", "st": "4.52"}, {"sp": "N", "t": "καὶ ὁ Σωκράτης ἀκούσας, Ἡράκλεις, ἔφη, τί τοσοῦτον νομίζοντες ἠδικῆσθαι ὑπὸ τοῦ σοῦ παιδὸς ὥστε ἀποκτεῖναι αὐτὸν βούλεσθαι; Ἀλλ᾽ οὔτοι, ἔφη, ἀποκτεῖναι βούλονται, ἀλλὰ πεῖσαι αὐτὸν συγκαθεύδειν αὐτοῖς. Σὺ δ᾽, ὡς ἔοικας, εἰ τοῦτο γένοιτο, νομίζεις ἂν διαφθαρῆναι αὐτόν; Ναὶ μὰ Δί᾽, ἔφη, παντάπασί γε.", "st": "4.53"}, {"sp": "N", "t": "Οὐδ᾽ αὐτὸς ἄρ᾽, ἔφη, συγκαθεύδεις αὐτῶι; Νὴ Δί᾽, ὅλας γε καὶ πάσας τὰς νύκτας. Νὴ τὴν Ἥραν, ἔφη ὁ Σωκράτης, εὐτύχημά γέ σου μέγα τὸ τὸν χρῶτα τοιοῦτον φῦναι ἔχοντα ὥστε μόνον μὴ διαφθείρειν τοὺς συγκαθεύδοντας. ὥστε σοί γε εἰ μὴ ἐπ᾽ ἄλλωι ἀλλ᾽ ἐπὶ τῶι χρωτὶ ἄξιον μέγα φρονεῖν.", "st": "4.54"}, {"sp": "N", "t": "Ἀλλὰ μὰ Δί᾽, ἔφη, οὐκ ἐπὶ τούτωι μέγα φρονῶ. Ἀλλ᾽ ἐπὶ τῶι μήν; Ἐπὶ νὴ Δία τοῖς ἄφροσιν. οὗτοι γὰρ τὰ ἐμὰ νευρόσπαστα θεώμενοι τρέφουσί με. Ταῦτ᾽ ἄρ᾽, ἔφη ὁ Φίλιππος, καὶ πρώιην ἐγώ σου ἤκουον εὐχομένου πρὸς τοὺς θεοὺς ὅπου ἂν ἦις διδόναι καρποῦ μὲν ἀφθονίαν, φρενῶν δὲ ἀφορίαν.", "st": "4.55"}, {"sp": "N", "t": "Εἶεν, ἔφη ὁ Καλλίας· σὺ δὲ δή, ὦ Σώκρατες, τί ἔχεις εἰπεῖν ὡς ἄξιόν σοί ἐστι μέγα φρονεῖν ἐφ᾽ ἧι εἶπας οὕτως ἀδόξωι οὔσηι τέχνηι; καὶ ὃς εἶπεν· Ὁμολογησώμεθα πρῶτον ποῖά ἐστιν ἔργα τοῦ μαστροποῦ· καὶ ὅσα ἂν ἐρωτῶ, μὴ ὀκνεῖτε ἀποκρίνεσθαι, ἵνα εἰδῶμεν ὅσα ἆν συνομολογῶμεν. καὶ ὑμῖν οὕτω δοκεῖ; ἔφη. Πάνυ μὲν οὖν, ἔφασαν. ὡς δ᾽ ἅπαξ εἶπαν Πάνυ μὲν οὖν, τοῦτο πάντες ἐκ τοῦ λοιποῦ ἀπεκρίναντο.", "st": "4.56"}, {"sp": "N", "t": "Οὐκοῦν ἀγαθοῦ μέν, ἔφη, ὑμῖν δοκεῖ μαστροποῦ ἔργον εἶναι ἣν ἂν ἢ ὃν ἂν μαστροπεύηι ἀρέσκοντα τοῦτον ἀποδεικνύναι οἷς ἂν συνῆι; Πάνυ μὲν οὖν, ἔφασαν. Οὐκοῦν ἓν μέν τί ἐστιν εἰς τὸ ἀρέσκειν ἐκ τοῦ πρέπουσαν ἔχειν σχέσιν καὶ τριχῶν καὶ ἐσθῆτος; Πάνυ μὲν οὖν, ἔφασαν.", "st": "4.57"}, {"sp": "N", "t": "Οὐκοῦν καὶ τόδε ἐπιστάμεθα, ὅτι ἔστιν ἀνθρώπωι τοῖς αὐτοῖς ὄμμασι καὶ φιλικῶς καὶ ἐχθρῶς πρός τινας βλέπειν; Πάνυ μὲν οὖν. Τί δέ, τῆι αὐτῆι φωνῆι ἔστι καὶ αἰδημόνως καὶ θρασέως φθέγγεσθαι; Πάνυ μὲν οὖν. Τί δέ, λόγοι οὐκ εἰσὶ μέν τινες ἀπεχθανόμενοι, εἰσὶ δέ τινες οἳ πρὸς φιλίαν ἄγουσι; Πάνυ μὲν οὖν.", "st": "4.58"}, {"sp": "N", "t": "Οὐκοῦν τούτων ὁ ἀγαθὸς μαστροπὸς τὰ συμφέροντα εἰς τὸ ἀρέσκειν διδάσκοι ἄν; Πάνυ μὲν οὖν. Ἀμείνων δ᾽ ἂν εἴη, ἔφη, ὁ ἑνὶ δυνάμενος ἀρεστοὺς ποιεῖν ἢ ὅστις καὶ πολλοῖς; ἐνταῦθα μέντοι ἐσχίσθησαν, καὶ οἱ μὲν εἶπον Δῆλον ὅτι ὅστις πλείστοις, οἱ δὲ Πάνυ μὲν οὖν.", "st": "4.59"}, {"sp": "N", "t": "ὁ δ᾽ εἰπὼν ὅτι καὶ τοῦτο ὁμολογεῖται ἔφη· Εἰ δέ τις καὶ ὅληι τῆι πόλει ἀρέσκοντας δύναιτο ἀποδεικνύναι, οὐχ οὗτος παντελῶς ἂν ἤδη ἀγαθὸς μαστροπὸς εἴη; Σαφῶς γε νὴ Δία, πάντες εἶπον. Οὐκοῦν εἴ τις τοιούτους δύναιτο ἐξεργάζεσθαι ὧν προστατοίη, δικαίως ἂν μέγα φρονοίη ἐπὶ τῆι τέχνηι καὶ δικαίως ἂν πολὺν μισθὸν λαμβάνοι;", "st": "4.60"}, {"sp": "N", "t": "ἐπεὶ δὲ καὶ ταῦτα πάντες συνωμολόγουν, Τοιοῦτος μέντοι, ἔφη, μοι δοκεῖ Ἀντισθένης εἶναι οὗτος. καὶ ὁ Ἀντισθένης, Ἐμοί, ἔφη, παραδίδως, ὦ Σώκρατες, τὴν τέχνην; Ναὶ μὰ Δί᾽, ἔφη. ὁρῶ γάρ σε καὶ τὴν ἀκόλουθον ταύτης πάνυ ἐξειργασμένον. Τίνα ταύτην; Τὴν προαγωγείαν, ἔφη.", "st": "4.61"}, {"sp": "N", "t": "καὶ ὃς μάλα ἀχθεσθεὶς ἐπήρετο· Καὶ τί μοι σύνοισθα, ὦ Σώκρατες, τοιοῦτον εἰργασμένωι; Οἶδα μέν, ἔφη, σε Καλλίαν τουτονὶ προαγωγεύσαντα τῶι σοφῶι Προδίκωι, ὅτε ἑώρας τοῦτον μὲν φιλοσοφίας ἐρῶντα, ἐκεῖνον δὲ χρημάτων δεόμενον· οἶδα δέ σε Ἱππίαι τῶι Ἠλείωι, παρ᾽ οὗ οὗτος καὶ τὸ μνημονικὸν ἔμαθεν· ἀφ᾽ οὗ δὴ καὶ ἐρωτικώτερος γεγένηται διὰ τὸ ὅ τι ἂν καλὸν ἴδηι μηδέποτε ἐπιλανθάνεσθαι.", "st": "4.62"}, {"sp": "N", "t": "ἔναγχος δὲ δήπου καὶ πρὸς ἐμὲ ἐπαινῶν τὸν Ἡρακλεώτην ξένον ἐπεί με ἐποίησας ἐπιθυμεῖν αὐτοῦ, συνέστησάς μοι αὐτόν. καὶ χάριν μέντοι σοι ἔχω· πάνυ γὰρ καλὸς κἀγαθὸς δοκεῖ μοι εἶναι. Αἰσχύλον δὲ τὸν Φλειάσιον πρὸς ἐμὲ ἐπαινῶν καὶ ἐμὲ πρὸς ἐκεῖνον οὐχ οὕτω διέθηκας ὥστε διὰ τοὺς σοὺς λόγους ἐρῶντες ἐκυνοδρομοῦμεν ἀλλήλους ζητοῦντες;", "st": "4.63"}, {"sp": "N", "t": "ταῦτα οὖν ὁρῶν δυνάμενόν σε ποιεῖν ἀγαθὸν νομίζω προαγωγὸν εἶναι. ὁ γὰρ οἷός τε ὢν γιγνώσκειν τε τοὺς ὠφελίμους αὑτοῖς καὶ τούτους δυνάμενος ποιεῖν ἐπιθυμεῖν ἀλλήλων, οὗτος ἄν μοι δοκεῖ καὶ πόλεις δύνασθαι φίλας ποιεῖν καὶ γάμους ἐπιτηδείους συνάγειν, καὶ πολλοῦ ἂν ἄξιος εἶναι καὶ πόλεσι καὶ φίλοις καὶ συμμάχοις κεκτῆσθαι. σὺ δὲ ὡς κακῶς ἀκούσας ὅτι ἀγαθόν σε ἔφην προαγωγὸν εἶναι, ὠργίσθης. Ἀλλὰ μὰ Δί᾽, ἔφη, οὐ νῦν. ἐὰν γὰρ ταῦτα δύνωμαι, σεσαγμένος δὴ παντάπασι πλούτου τὴν ψυχὴν ἔσομαι. καὶ αὕτη μὲν δὴ ἡ περίοδος τῶν λόγων ἀπετελέσθη.", "st": "4.64"}, {"sp": "N", "t": "Ὁ δὲ Καλλίας ἔφη· Σὺ δὲ δή, ὦ Κριτόβουλε, εἰς τὸν περὶ τοῦ κάλλους ἀγῶνα πρὸς Σωκράτην οὐκ ἀνθίστασαι; Νὴ Δί᾽, ἔφη ὁ Σωκράτης, ἴσως γὰρ εὐδοκιμοῦντα τὸν μαστροπὸν παρὰ τοῖς κριταῖς ὁρᾶι.", "st": "5.1"}, {"sp": "N", "t": "Ἀλλ᾽ ὅμως, ἔφη ὁ Κριτόβουλος, οὐκ ἀναδύομαι· ἀλλὰ δίδασκε, εἴ τι ἔχεις σοφόν, ὡς καλλίων εἶ ἐμοῦ. μόνον, ἔφη, τὸν λαμπτῆρα ἐγγὺς προσενεγκάτω. Εἰς ἀνάκρισιν τοίνυν σε, ἔφη, πρῶτον τῆς δίκης καλοῦμαι· ἀλλ᾽ ἀποκρίνου.", "st": "5.2"}, {"sp": "N", "t": "Σὺ δέ γε ἐρώτα. Πότερον οὖν ἐν ἀνθρώπωι μόνον νομίζεις τὸ καλὸν εἶναι ἢ καὶ ἐν ἄλλωι τινί; Ἐγὼ μὲν ναὶ μὰ Δί᾽, ἔφη, καὶ ἐν ἵππωι καὶ βοῒ καὶ ἐν ἀψύχοις πολλοῖς. οἶδα γοῦν οὖσαν καὶ ἀσπίδα καλὴν καὶ ξίφος καὶ δόρυ.", "st": "5.3"}, {"sp": "N", "t": "Καὶ πῶς, ἔφη, οἷόν τε ταῦτα μηδὲν ὅμοια ὄντα ἀλλήλοις πάντα καλὰ εἶναι; Ἂν νὴ Δί᾽, ἔφη, πρὸς τὰ ἔργα ὧν ἕνεκα ἔκαστα κτώμεθα εὖ εἰργασμένα ἦι ἢ εὖ πεφυκότα πρὸς ἃ ἂν δεώμεθα, καὶ ταῦτ᾽, ἔφη ὁ Κριτόβουλος, καλά.", "st": "5.4"}, {"sp": "N", "t": "Οἶσθα οὖν, ἔφη, ὀφθαλμῶν τίνος ἕνεκα δεόμεθα; Δῆλον, ἔφη, ὅτι τοῦ ὁρᾶν. Οὕτω μὲν τοίνυν ἤδη οἱ ἐμοὶ ὀφθαλμοὶ καλλίονες ἂν τῶν σῶν εἴησαν. Πῶς δή; Ὅτι οἱ μὲν σοὶ τὸ κατ᾽ εὐθὺ μόνον ὁρῶσιν, οἱ δὲ ἐμοὶ καὶ τὸ ἐκ πλαγίου διὰ τὸ ἐπιπόλαιοι εἶναι. Λέγεις σύ, ἔφη, καρκίνον εὐοφθαλμότατον εἶναι τῶν ζώιων; Πάντως δήπου, ἔφη· ἐπεὶ καὶ πρὸς ἰσχὺν τοὺς ὀφθαλμοὺς ἄριστα πεφυκότας ἔχει.", "st": "5.5"}, {"sp": "N", "t": "Εἶεν, ἔφη, τῶν δὲ ῥινῶν ποτέρα καλλίων, ἡ σὴ ἢ ἡ ἐμή; Ἐγὼ μέν, ἔφη, οἶμαι τὴν ἐμήν, εἴπερ γε τοῦ ὀσφραίνεσθαι ἕνεκεν ἐποίησαν ἡμῖν ῥῖνας οἱ θεοί. οἱ μὲν γὰρ σοὶ μυκτῆρες εἰς γῆν ὁρῶσιν, οἱ δὲ ἐμοὶ ἀναπέπτανται, ὥστε τὰς πάντοθεν ὀσμὰς προσδέχεσθαι. Τὸ δὲ δὴ σιμὸν τῆς ῥινὸς πῶς τοῦ ὀρθοῦ κάλλιον; Ὅτι, ἔφη, οὐκ ἀντιφράττει, ἀλλ᾽ ἐᾶι εὐθὺς τὰς ὄψεις ὁρᾶν ἆ ἂν βούλωνται· ἡ δὲ ὑψηλὴ ῥὶς ὥσπερ ἐπηρεάζουσα διατετείχικε τὰ ὄμματα.", "st": "5.6"}, {"sp": "N", "t": "Τοῦ γε μὴν στόματος, ἔφη ὁ Κριτόβουλος, ὑφίεμαι. εἰ γὰρ τοῦ ἀποδάκνειν ἕνεκα πεποίηται, πολὺ ἂν σὺ μεῖζον ἢ ἐγὼ ἀποδάκοις. διὰ δὲ τὸ παχέα ἔχειν τὰ χείλη οὐκ οἴει καὶ μαλακώτερόν σου ἔχειν τὸ φίλημα; Ἔοικα, ἔφη, ἐγὼ κατὰ τὸν σὸν λόγον καὶ τῶν ὄνων αἴσχιον τὸ στόμα ἔχειν. ἐκεῖνο δὲ οὐδὲν τεκμήριον λογίζηι, ὡς ἐγὼ σοῦ καλλίων εἰμί, ὅτι καὶ Ναΐδες θεοὶ οὖσαι τοὺς Σειληνοὺς ἐμοὶ ὁμοιοτέρους τίκτουσιν ἢ σοί;", "st": "5.7"}, {"sp": "N", "t": "καὶ ὁ Κριτόβουλος, Οὐκέτι, ἔφη ἔχω πρὸς σὲ ἀντιλέγειν, ἀλλὰ διαφερόντων, ἔφη, τὰς ψήφους, ἵνα ὡς τάχιστα εἰδῶ ὅ τι με χρὴ παθεῖν ἢ ἀποτεῖσαι. μόνον, ἔφη, κρυφῆι φερόντων· δέδοικα γὰρ τὸν σὸν καὶ Ἀντισθένους πλοῦτον μή με καταδυναστεύσηι.", "st": "5.8"}, {"sp": "N", "t": "ἡ μὲν δὴ παῖς καὶ ὁ παῖς κρύφα ἀνέφερον. ὁ δὲ Σωκράτης ἐν τούτωι διέπραττε τόν τε λύχνον ἀντιπροσενεγκεῖν τῶι Κριτοβούλωι, ὡς μὴ ἐξαπατηθείησαν οἱ κριταί, καὶ τῶι νικήσαντι μὴ ταινίας ἀλλὰ φιλήματα ἀναδήματα παρὰ τῶν κριτῶν γενέσθαι.", "st": "5.9"}, {"sp": "N", "t": "ἐπεὶ δὲ ἐξέπεσον αἱ ψῆφοι καὶ ἐγένοντο πᾶσαι σὺν Κριτοβούλωι, Παπαῖ, ἔφη ὁ Σωκράτης, οὐχ ὅμοιον ἔοικε τὸ σὸν ἀργύριον, ὦ Κριτόβουλε, τῶι Καλλίου εἶναι. τὸ μὲν γὰρ τούτου δικαιοτέρους ποιεῖ, τὸ δὲ σὸν ὥσπερ τὸ πλεῖστον διαφθείρειν ἱκανόν ἐστι καὶ δικαστὰς καὶ κριτάς.", "st": "5.10"}, {"sp": "N", "t": "Ἐκ δὲ τούτου οἱ μὲν τὰ νικητήρια φιλήματα ἀπολαμβάνειν τὸν Κριτόβουλον ἐκέλευον, οἱ δὲ τὸν κύριον πείθειν, οἱ δὲ καὶ ἄλλα ἔσκωπτον. ὁ δὲ Ἑρμογένης κἀνταῦθα ἐσιώπα. καὶ ὁ Σωκράτης ὀνομάσας αὐτόν, Ἔχοις ἄν, ἔφη, ὦ Ἑρμόγενες, εἰπεῖν ἡμῖν τί ἐστὶ παροινία; καὶ ὃς ἀπεκρίνατο· Εἰ μὲν ὅ τι ἐστὶν ἐρωτᾶις, οὐκ οἶδα· τὸ μέντοι μοι δοκοῦν εἴποιμ᾽ ἄν. Ἀλλ᾽, ὃ δοκεῖ, τοῦτ᾽, ἔφη.", "st": "6.1"}, {"sp": "N", "t": "Τὸ τοίνυν παρ᾽ οἶνον λυπεῖν τοὺς συνόντας, τοῦτ᾽ ἐγὼ κρίνω παροινίαν. Οἶσθ᾽ οὖν, ἔφη, ὅτι καὶ σὺ νῦν ἡμᾶς λυπεῖς σιωπῶν; Ἦ καὶ ὅταν λέγητ᾽; ἔφη. Οὐκ ἀλλ᾽ ὅταν διαλίπωμεν. Ἦ οὖν λέληθέ σε ὅτι μεταξὺ τοῦ ὑμᾶς λέγειν οὐδ᾽ ἂν τρίχα, μὴ ὅτι λόγον ἄν τις παρείρειε;", "st": "6.2"}, {"sp": "N", "t": "καὶ ὁ Σωκράτης, Ὦ Καλλία, ἔχοις ἄν τι, ἔφη, ἀνδρὶ ἐλεγχομένωι βοηθῆσαι; Ἔγωγ᾽, ἔφη. ὅταν γὰρ ὁ αὐλὸς φθέγγηται, παντάπασι σιωπῶμεν. καὶ ὁ Ἑρμογένης, Ἦ οὖν βούλεσθε, ἔφη, ὥσπερ Νικόστρατος ὁ ὑποκριτὴς τετράμετρα πρὸς τὸν αὐλὸν κατέλεγεν, οὕτω καὶ ὑπὸ τοῦ αὐλοῦ ὑμῖν διαλέγωμαι;", "st": "6.3"}, {"sp": "N", "t": "καὶ ὁ Σωκράτης, Πρὸς τῶν θεῶν, ἔφη, Ἑρμόγενες, οὕτω ποίει. οἶμαι γάρ, ὥσπερ ἡ ὠιδὴ ἡδίων πρὸς τὸν αὐλόν, οὕτω καὶ τοὺς σοὺς λόγους ἡδύνεσθαι ἄν τι ὑπὸ τῶν φθόγγων, ἄλλως τε καὶ εἰ μορφάζοις, ὥσπερ ἡ αὐλητρίς, καὶ σὺ πρὸς τὰ λεγόμενα.", "st": "6.4"}, {"sp": "N", "t": "καὶ ὁ Καλλίας ἔφη· Ὅταν οὖν ὁ Ἀντισθένης ὅδ᾽ ἐλέγχηι τινὰ ἐν τῶι συμποσίωι, τί ἔσται τὸ αὔλημα; καὶ ὁ Ἀντισθένης εἶπε· Τῶι μὲν ἐλεγχομένωι οἶμαι ἄν, ἔφη, πρέπειν συριγμόν.", "st": "6.5"}, {"sp": "N", "t": "Τοιούτων δὲ λόγων ὄντων ὡς ἑώρα ὁ Συρακόσιος τῶν μὲν αὑτοῦ ἐπιδειγμάτων ἀμελοῦντας, ἀλλήλοις δὲ ἡδομένους, φθονῶν τῶι Σωκράτει εἶπεν· Ἆρα σύ, ὦ Σώκρατες, ὁ φροντιστὴς ἐπικαλούμενος; Οὐκοῦν κάλλιον, ἔφη, ἢ εἰ ἀφρόντιστος ἐκαλούμην. Εἰ μή γε ἐδόκεις τῶν μετεώρων φροντιστὴς εἶναι.", "st": "6.6"}, {"sp": "N", "t": "Οἶσθα οὖν, ἔφη ὁ Σωκράτης, μετεωρότερόν τι τῶν θεῶν; Ἀλλ᾽ οὐ μὰ Δί᾽, ἔφη, οὐ τούτων σε λέγουσιν ἐπιμελεῖσθαι, ἀλλὰ τῶν ἀνωφελεστάτων. Οὐκοῦν καὶ οὕτως ἄν, ἔφη, θεῶν ἐπιμελοίμην· ἄνωθεν μέν γε ὕοντες ὠφελοῦσιν, ἄνωθεν δὲ φῶς παρέχουσιν. εἰ δὲ ψυχρὰ λέγω, σὺ αἴτιος, ἔφη, πράγματά μοι παρέχων.", "st": "6.7"}, {"sp": "N", "t": "Ταῦτα μέν, ἔφη, ἔα· ἀλλ᾽ εἰπέ μοι πόσους ψύλλα πόδας ἐμοῦ ἀπέχει. ταῦτα γάρ σέ φασι γεωμετρεῖν. καὶ ὁ Ἀντισθένης εἶπε· Σὺ μέντοι δεινὸς εἶ, ὦ Φίλιππε, εἰκάζειν· οὐ δοκεῖ σοι ὁ ἀνὴρ οὗτος λοιδορεῖσθαι βουλομένωι ἐοικέναι; ναὶ μὰ τὸν Δί᾽, ἔφη, καὶ ἄλλοις γε πολλοῖς.", "st": "6.8"}, {"sp": "N", "t": "Ἀλλ᾽ ὅμως, ἔφη ὁ Σωκράτης, σὺ αὐτὸν μὴ εἴκαζε, ἵνα μὴ καὶ σὺ λοιδορουμένωι ἐοίκηις. Ἀλλ᾽ εἴπερ γε τοῖς πᾶσι καλοῖς καὶ τοῖς βελτίστοις εἰκάζω αὐτόν, ἐπαινοῦντι μᾶλλον ἢ λοιδορουμένωι δικαίως ἂν εἰκάζοι μέ τις. Καὶ νῦν σύγε λοιδορουμένωι ἔοικας, εἰ πάντ᾽ αὐτοῦ βελτίω φὴις εἶναι.", "st": "6.9"}, {"sp": "N", "t": "Ἀλλὰ βούλει πονηροτέροις εἰκάζω αὐτόν; Μηδὲ πονηροτέροις. Ἀλλὰ μηδενί; Μηδενὶ μηδὲ⟨ν⟩ το⟨ῦτο⟩ν εἴκαζε. Ἀλλ᾽ οὐ μέντοι γε σιωπῶν οἶδα ὅπως ἄξια τοῦ δείπνου ἐργάσομαι. Καὶ ῥαιδίως γ᾽, ἂν ἃ μὴ δεῖ λέγειν, ἔφη, σιωπᾶις. αὕτη μὲν δὴ ἡ παροινία οὕτω κατεσβέσθη.", "st": "6.10"}, {"sp": "N", "t": "Ἐκ τούτου δὲ τῶν ἄλλων οἱ μὲν ἐκέλευον εἰκάζειν, οἱ δὲ ἐκώλυον. θορύβου δὲ ὄντος ὁ Σωκράτης αὖ πάλιν εἶπεν· Ἆρα ἐπειδὴ πάντες ἐπιθυμοῦμεν λέγειν, νῦν ἂν μάλιστα καὶ ἅμα ἄισαιμεν; καὶ εὐθὺς τοῦτ᾽ εἰπὼν ἦρχεν ὠιδῆς.", "st": "7.1"}, {"sp": "N", "t": "ἐπεὶ δ᾽ ἦισεν, εἰσεφέρετο τῆι ὀρχηστρίδι τροχὸς τῶν κεραμεικῶν, ἐφ᾽ οὗ ἔμελλε θαυματουργήσειν. ἔνθα δὴ εἶπεν ὁ Σωκράτης· Ὦ Συρακόσιε, κινδυνεύω ἐγώ, ὥσπερ σὺ λέγεις, τῶι ὄντι φροντιστὴς εἶναι· νῦν γοῦν σκοπῶ ὅπως ἂν ὁ μὲν παῖς ὅδε ὁ σὸς καὶ ἡ παῖς ἥδε ὡς ῥᾶιστα διάγοιεν, ἡμεῖς δ᾽ ἂν μάλιστα εὐφραινοίμεθα θεώμενοι αὐτούς· ὅπερ εὖ οἶδα ὅτι καὶ σὺ βούλει.", "st": "7.2"}, {"sp": "N", "t": "δοκεῖ οὖν μοι τὸ μὲν εἰς μαχαίρας κυβιστᾶν κινδύνου ἐπίδειγμα εἶναι, ὃ συμποσίωι οὐδὲν προσήκει. καὶ μὴν τό γε ἐπὶ τοῦ τροχοῦ ἅμα περιδινουμένου γράφειν τε καὶ ἀναγιγνώσκειν θαῦμα μὲν ἴσως τί ἐστιν, ἡδονὴν δὲ οὐδὲ ταῦτα δύναμαι γνῶναι τίν᾽ ἂν παράσχοι. οὐδὲ μὴν τό γε διαστρέφοντας τὰ σώματα καὶ τροχοὺς μιμουμένους ἥδιον ἢ ἡσυχίαν ἔχοντας τοὺς καλοὺς καὶ ὡραίους θεωρεῖν.", "st": "7.3"}, {"sp": "N", "t": "καὶ γὰρ δὴ οὐδὲ πάνυ τι σπάνιον τό γε θαυμασίοις ἐντυχεῖν, εἴ τις τούτου δεῖται, ἀλλ᾽ ἔξεστιν αὐτίκα μάλα τὰ παρόντα θαυμάζειν, τί ποτε ὁ μὲν λύχνος διὰ τὸ λαμπρὰν φλόγα ἕχειν φῶς παρέχει, τὸ δὲ χαλκεῖον λαμπρὸν ὂν φῶς μὲν οὐ ποιεῖ, ἐν αὑτῶι δὲ ἄλλα ἐμφαινόμενα παρέχεται· καὶ πῶς τὸ μὲν ἔλαιον ὑγρὸν ὂν αὔξει τὴν φλόγα, τὸ δὲ ὕδωρ, ὅτι ὑγρόν ἐστι, κατασβέννυσι τὸ πῦρ. ἀλλὰ γὰρ καὶ ταῦτα μὲν οὐκ εἰς ταὐτὸν τῶι οἴνωι ἐπισπεύδει·", "st": "7.4"}, {"sp": "N", "t": "εἰ δὲ ὀρχοῖντο πρὸς τὸν αὐλὸν σχήματα ἐν οἷς Χάριτές τε καὶ Ὧραι καὶ Νύμφαι γράφονται, πολὺ ἂν οἶμαι αὐτούς γε ῥᾶιον διάγειν καὶ τὸ συμπόσιον πολὺ ἐπιχαριτώτερον εἶναι. ὁ οὖν Συρακόσιος, Ἀλλὰ ναὶ μὰ τὸν Δί᾽, ἔφη, ὦ Σώκρατες, καλῶς τε λέγεις καὶ ἐγὼ εἰσάξω θεάματα ἐφ᾽ οἷς ὑμεῖς εὐφρανεῖσθε.", "st": "7.5"}, {"sp": "N", "t": "Ὁ μὲν δὴ Συρακόσιος ἐξελθὼν συνεκροτεῖτο· ὁ δὲ Σωκράτης πάλιν αὖ καινοῦ λόγου κατῆρχεν. Ἆρ᾽, ἔφη, ὦ ἄνδρες, εἰκὸς ἡμᾶς παρόντος δαίμονος μεγάλου καὶ τῶι μὲν χρόνωι ἰσήλικος τοῖς ἀειγενέσι θεοῖς, τῆι δὲ μορφῆι νεωτάτου, καὶ μεγέθει πάντα ἐπέχοντος, ψυχῆι δὲ ἀνθρώπου ἱδρυμένου, Ἔρωτος, μὴ ἀμνημονῆσαι, ἄλλως τε καὶ ἐπειδὴ πάντες ἐσμὲν τοῦ θεοῦ τούτου θιασῶται;", "st": "8.1"}, {"sp": "N", "t": "ἐγώ τε γὰρ οὐκ ἔχω χρόνον εἰπεῖν ἐν ὧι οὐκ ἐρῶν τινος διατελῶ, Χαρμίδην δὲ τόνδε οἶδα πολλοὺς μὲν ἐραστὰς κτησάμενον, ἔστι δὲ ὧν καὶ αὐτὸν ἐπιθυμήσαντα· Κριτόβουλός γε μὴν ἔτι καὶ νῦν ἐρώμενος ὢν ἤδη ἄλλων ἐπιθυμεῖ.", "st": "8.2"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ ὁ Νικήρατος, ὡς ἐγὼ ἀκούω, ἐρῶν τῆς γυναικὸς ἀντερᾶται. Ἑρμογένη γε μὴν τίς ἡμῶν οὐκ οἶδεν ὡς, ὅ τι ποτ᾽ ἐστὶν ἡ καλοκἀγαθία, τῶι ταύτης ἔρωτι κατατήκεται; οὐχ ὁρᾶτε ὡς σπουδαῖαι μὲν αὐτοῦ αἱ ὀφρύες, ἀτρεμὲς δὲ τὸ ὄμμα, μέτριοι δὲ οἱ λόγοι, πραεῖα δὲ ἡ φωνή, ἱλαρὸν δὲ τὸ ἦθος; τοῖς δὲ σεμνοτάτοις θεοῖς φίλοις χρώμενος οὐδὲν ἡμᾶς τοὺς ἀνθρώπους ὑπερορᾶι; σὺ δὲ μόνος, ὦ Ἀντίσθενες, οὐδενὸς ἐρᾶις;", "st": "8.3"}, {"sp": "N", "t": "Ναὶ μὰ τοὺς θεούς, εἶπεν ἐκεῖνος, καὶ σφόδρα γε σοῦ. καὶ ὁ Σωκράτης ἐπισκώψας ὡς δὴ θρυπτόμενος εἶπε· Μὴ νῦν μοι ἐν τῶι παρόντι ὄχλον πάρεχε· ὡς γὰρ ὁρᾶις, ἄλλα πράττω.", "st": "8.4"}, {"sp": "N", "t": "καὶ ὁ Ἀντισθένης ἔλεξεν· Ὡς σαφῶς μέντοι σὺ μαστροπὲ σαυτοῦ ἀεὶ τοιαῦτα ποιεῖς· τοτὲ μὲν τὸ δαιμόνιον προφασιζόμενος οὐ διαλέγηι μοι, τοτὲ δ᾽ ἄλλου του ἐφιέμενος.", "st": "8.5"}, {"sp": "N", "t": "καὶ ὁ Σωκράτης ἔφη· Πρὸς τῶν θεῶν, ὦ Ἀντίσθενες, μόνον μὴ συγκόψηις με· τὴν δ᾽ ἄλλην χαλεπότητα ἐγώ σου καὶ φέρω καὶ οἴσω φιλικῶς. ἀλλὰ γάρ, ἔφη, τὸν μὲν σὸν ἔρωτα κρύπτωμεν, ἐπειδὴ καὶ ἔστιν οὐ ψυχῆς ἀλλ᾽ εὐμορφίας τῆς ἐμῆς.", "st": "8.6"}, {"sp": "N", "t": "ὅτι γε μὴν σύ, ὦ Καλλία, ἐρᾶις Αὐτολύκου πᾶσα μὲν ἡ πόλις οἶδε, πολλοὺς δ᾽ οἶμαι καὶ τῶν ξένων. τούτου δ᾽ αἴτιον τὸ πατέρων τε ὀνομαστῶν ἀμφοτέρους ὑμᾶς εἶναι καὶ αὐτοὺς ἐπιφανεῖς.", "st": "8.7"}, {"sp": "N", "t": "ἀεὶ μὲν οὖν ἔγωγε ἠγάμην τὴν σὴν φύσιν, νῦν δὲ καὶ πολὺ μᾶλλον, ἐπεὶ ὁρῶ σε ἐρῶντα οὐχ ἁβρότητι χλιδαινομένου οὐδὲ μαλακίαι θρυπτομένου, ἀλλὰ πᾶσιν ἐπιδεικνυμένου ῥώμην τε καὶ καρτερίαν καὶ ἀνδρείαν καὶ σωφροσύνην. τὸ δὲ τοιούτων ἐπιθυμεῖν τεκμήριόν ἐστι ⟨καὶ⟩ τῆς τοῦ ἐραστοῦ φύσεως.", "st": "8.8"}, {"sp": "N", "t": "εἰ μὲν οὖν μία ἐστὶν Ἀφροδίτη ἢ διτταί, Οὐρανία τε καὶ Πάνδημος, οὐκ οἶδα· καὶ γὰρ Ζεὺς ὁ αὐτὸς δοκῶν εἶναι πολλὰς ἐπωνυμίας ἔχει· ὅτι γε μέντοι χωρὶς ἑκατέραι βωμοί τε καὶ ναοί εἰσι καὶ θυσίαι τῆι μὲν Πανδήμωι ῥαιδιουργότεραι, τῆι δὲ Οὐρανίαι ἁγνότεραι, οἶδα.", "st": "8.9"}, {"sp": "N", "t": "εἰκάσαις δ᾽ ἂν καὶ τοὺς ἔρωτας τὴν μὲν Πάνδημον τῶν σωμάτων ἐπιπέμπειν, τὴν δ᾽ Οὐρανίαν τῆς ψυχῆς τε καὶ τῆς φιλίας καὶ τῶν καλῶν ἔργων. ὑφ᾽ οὗ δὴ καὶ σύ, ὦ Καλλία, κατέχεσθαί μοι δοκεῖς ἔρωτος.", "st": "8.10"}, {"sp": "N", "t": "τεκμαίρομαι δὲ τῆι τοῦ ἐρωμένου καλοκἀγαθίαι καὶ ὅτι σε ὁρῶ τὸν πατέρα αὐτοῦ παραλαμβάνοντα εἰς τὰς πρὸς τοῦτον συνουσίας. οὐδὲν γὰρ τούτων ἐστὶν ἀπόκρυφον πατρὸς τῶι καλῶι τε κἀγαθῶι ἐραστῆι.", "st": "8.11"}, {"sp": "N", "t": "καὶ ὁ Ἑρμογένης εἶπε· Νὴ τὴν Ἥραν, ἔφη, ὦ Σώκρατες, ἄλλα τέ σου πολλὰ ἄγαμαι καὶ ὅτι νῦν ἅμα χαριζόμενος Καλλίαι καὶ παιδεύεις αὐτὸν οἷόνπερ χρὴ εἶναι. Νὴ Δί᾽, ἔφη, ὅπως δὲ καὶ ἔτι μᾶλλον εὐφραίνηται, βούλομαι αὐτῶι μαρτυρῆσαι ὡς καὶ πολὺ κρείττων ἐστὶν ὁ τῆς ψυχῆς ἢ ὁ τοῦ σώματος ἔρως.", "st": "8.12"}, {"sp": "N", "t": "ὅτι μὲν γὰρ δὴ ἄνευ φιλίας συνουσία οὐδεμία ἀξιόλογος πάντες ἐπιστάμεθα. φιλεῖν γε μὴν τῶν μὲν τὸ ἦθος ἀγαμένων ἀνάγκη ἡδεῖα καὶ ἐθελουσία καλεῖται· τῶν δὲ τοῦ σώματος ἐπιθυμούντων πολλοὶ μὲν τοὺς τρόπους μέμφονται καὶ μισοῦσι τῶν ἐρωμένων·", "st": "8.13"}, {"sp": "N", "t": "ἂν δὲ καὶ ἀμφότερα στέρξωσι, τὸ μὲν τῆς ὥρας ἄνθος ταχὺ δήπου παρακμάζει, ἀπολείποντος δὲ τούτου ἀνάγκη καὶ τὴν φιλίαν συναπομαραίνεσθαι, ἡ δὲ ψυχὴ ὅσονπερ ἂν χρόνον ἴηι ἐπὶ τὸ φρονιμώτερον καὶ ἀξιεραστοτέρα γίγνεται.", "st": "8.14"}, {"sp": "N", "t": "καὶ μὴν ἐν μὲν τῆι τῆς μορφῆς χρήσει ἔνεστί τις καὶ κόρος, ὥστε ἅπερ καὶ πρὸς τὰ σιτία διὰ πλησμονήν, ταῦτα ἀνάγκη καὶ πρὸς τὰ παιδικὰ πάσχειν· ἡ δὲ τῆς ψυχῆς φιλία διὰ τὸ ἁγνὴ εἶναι καὶ ἀκορεστοτέρα ἐστίν, οὐ μέντοι, ὥς γ᾽ ἄν τις οἰηθείη, διὰ τοῦτο καὶ ἀνεπαφροδιτοτέρα, ἀλλὰ σαφῶς καὶ ἀποτελεῖται ἡ εὐχὴ ἐν ἧι αἰτούμεθα τὴν θεὸν ἐπαφρόδιτα καὶ ἔπη καὶ ἔργα διδόναι.", "st": "8.15"}, {"sp": "N", "t": "ὡς μὲν γὰρ ἄγαταί τε καὶ φιλεῖ τὸν ἐρώμενον θάλλουσα μορφῆι τε ἐλευθερίαι καὶ ἤθει αἰδήμονί τε καὶ γενναίωι ψυχὴ εὐθὺς ἐν τοῖς ἥλιξιν ἡγεμονική τε ἅμα καὶ φιλόφρων οὖσα οὐδὲν ἐπιδεῖται λόγου· ὅτι δὲ εἰκὸς καὶ ὑπὸ τῶν παιδικῶν τὸν τοιοῦτον ἐραστὴν ἀντιφιλεῖσθαι, καὶ τοῦτο διδάξω.", "st": "8.16"}, {"sp": "N", "t": "πρῶτον μὲν γὰρ τίς μισεῖν δύναιτ᾽ ἂν ὑφ᾽ οὗ εἰδείη καλός τε καὶ ἀγαθὸς νομιζόμενος; ἔπειτα δὲ ὁρώιη αὐτὸν τὰ τοῦ παιδὸς καλὰ μᾶλλον ἢ τὰ ἑαυτοῦ ἡδέα σπουδάζοντα; πρὸς δὲ τούτοις πιστεύοι μήτ᾽ ἂν ⟨παρανθήσηι⟩ μήτ᾽ ἂν καμὼν ἀμορφότερος γένηται, μειωθῆναι ἂν τὴν φιλίαν;", "st": "8.17"}, {"sp": "N", "t": "οἷς γε μὴν κοινὸν τὸ φιλεῖσθαι, πῶς οὐκ ἀνάγκη τούτους ἡδέως μὲν προσορᾶν ἀλλήλους, εὐνοϊκῶς δὲ διαλέγεσθαι, πιστεύειν δὲ καὶ πιστεύεσθαι, καὶ προνοεῖν μὲν ἀλλήλων, συνήδεσθαι δ᾽ ἐπὶ ταῖς καλαῖς πράξεσι, συνάχθεσθαι δὲ ἄν τι σφάλμα προσπίπτηι, τότε δ᾽ εὐφραινομένους διατελεῖν, ὅταν ὑγιαίνοντες συνῶσιν, ἂν δὲ κάμηι ὁπότερος οὖν, πολὺ συνεχεστέραν τὴν συνουσίαν ἔχειν, καὶ ἀπόντων ἔτι μᾶλλον ἢ παρόντων ἐπιμελεῖσθαι; οὐ ταῦτα πάντα ἐπαφρόδιτα; διά γέ τοι τὰ τοιαῦτα ἔργα ἅμα ἐρῶντες τῆς φιλίας καὶ χρώμενοι αὐτῆι εἰς γῆρας διατελοῦσι.", "st": "8.18"}, {"sp": "N", "t": "τὸν δὲ ἐκ τοῦ σώματος κρεμάμενον διὰ τί ἀντιφιλήσειεν ἂν ὁ παῖς; πότερον ὅτι ἑαυτῶι μὲν νέμει ὧν ἐπιθυμεῖ, τῶι δὲ παιδὶ τὰ ἐπονειδιστότατα; ἢ διότι ἃ σπεύδει πράττειν παρὰ τῶν παιδικῶν, εἴργει μάλιστα τοὺς οἰκείους ἀπὸ τούτων;", "st": "8.19"}, {"sp": "N", "t": "καὶ μὴν ὅτι γε οὐ βιάζεται, ἀλλὰ πείθει, διὰ τοῦτο μᾶλλον μισητέος. ὁ μὲν γὰρ βιαζόμενος ἑαυτὸν πονηρὸν ἀποδεικνύει, ὁ δὲ πείθων τὴν τοῦ ἀναπειθομένου ψυχὴν διαφθείρει.", "st": "8.20"}, {"sp": "N", "t": "ἀλλὰ μὴν καὶ ὁ χρημάτων γε ἀπεμπολῶν τὴν ὥραν τί μᾶλλον στέρξει τὸν πριάμενον ἢ ὁ ἐν ἀγορᾶι πωλῶν καὶ ἀποδιδόμενος; οὐ μὴν ὅτι γε ὡραῖος ἀώρωι, οὐδὲ ὅτι γε καλὸς οὐκέτι καλῶι καὶ ἐρῶντι οὐκ ἐρῶν ὁμιλεῖ, φιλήσει αὐτόν. οὐδὲ γὰρ ὁ παῖς τῶι ἀνδρὶ ὥσπερ γυνὴ κοινωνεῖ τῶν ἐν τοῖς ἀφροδισίοις εὐφροσυνῶν, ἀλλὰ νήφων μεθύοντα ὑπὸ τῆς ἀφροδίτης θεᾶται.", "st": "8.21"}, {"sp": "N", "t": "ἐξ ὧν οὐδὲν θαυμαστὸν εἰ καὶ τὸ ὑπερορᾶν ἐγγίγνεται αὐτῶι τοῦ ἐραστοῦ. καὶ σκοπῶν δ᾽ ἄν τις εὕροι ἐκ μὲν τῶν διὰ τοὺς τρόπους φιλουμένων οὐδὲν χαλεπὸν γεγενημένον, ἐκ δὲ τῆς ἀναιδοῦς ὁμιλίας πολλὰ ἤδη καὶ ἀνόσια πεπραγμένα.", "st": "8.22"}, {"sp": "N", "t": "ὡς δὲ καὶ ἀνελεύθερος ἡ συνουσία τῶι τὸ σῶμα μᾶλλον ἢ τῶι τὴν ψυχὴν ἀγαπῶντι, νῦν τοῦτο δηλώσω. ὁ μὲν γὰρ παιδεύων λέγειν τε ἃ δεῖ καὶ πράττειν δικαίως ἂν ὥσπερ Χείρων καὶ Φοῖνιξ ὑπ᾽ Ἀχιλλέως τιμῶιτο, ὁ δὲ τοῦ σώματος ὀρεγόμενος εἰκότως ἂν ὥσπερ πτωχὸς περιέποιτο. ἀεὶ γάρ τοι προσαιτῶν καὶ προσδεόμενος ἢ φιλήματος ἢ ἄλλου τινὸς ψηλαφήματος παρακολουθεῖ.", "st": "8.23"}, {"sp": "N", "t": "εἰ δὲ λαμυρώτερον λέγω, μὴ θαυμάζετε· ὅ τε γὰρ οἶνος συνεπαίρει καὶ ὁ ἀεὶ σύνοικος ἐμοὶ ἔρως κεντρίζει εἰς τὸν ἀντίπαλον ἔρωτα αὐτῶι παρρησιάζεσθαι.", "st": "8.24"}, {"sp": "N", "t": "καὶ γὰρ δὴ δοκεῖ μοι ὁ μὲν τῶι εἴδει τὸν νοῦν προσέχων μεμισθωμένωι χῶρον ἐοικέναι. οὐ γὰρ ὅπως πλείονος ἄξιος γένηται ἐπιμελεῖται, ἀλλ᾽ ὅπως αὐτὸς ὅτι πλεῖστα ὡραῖα καρπώσεται. ὁ δὲ τῆς φιλίας ἐφιέμενος μᾶλλον ἔοικε τῶι τὸν οἰκεῖον ἀγρὸν κεκτημένωι· πάντοθεν γοῦν φέρων ὅ τι ἂν δύνηται πλείονος ἄξιον ποιεῖ τὸν ἐρώμενον.", "st": "8.25"}, {"sp": "N", "t": "καὶ μὴν καὶ τῶν παιδικῶν ὃς μὲν ἂν εἰδῆι ὅτι ὁ τοῦ εἴδους ἐπαρκῶν ἄρξει τοῦ ἐραστοῦ, εἰκὸς αὐτὸν τἆλλα ῥαιδιουργεῖν· ὃς δ᾽ ἂν γιγνώσκηι ὅτι ἂν μὴ καλὸς κἀγαθὸς ἦι, οὐ καθέξει τὴν φιλίαν, τοῦτον προσήκει μᾶλλον ἀρετῆς ἐπιμελεῖσθαι.", "st": "8.26"}, {"sp": "N", "t": "μέγιστον δ᾽ ἀγαθὸν τῶι ὀρεγομένωι ἐκ παιδικῶν φίλον ἀγαθὸν ποιήσασθαι ὅτι ἀνάγκη καὶ αὐτὸν ἀσκεῖν ἀρετήν. οὐ γὰρ οἶόν τε πονηρὰ αὐτὸν ποιοῦντα ἀγαθὸν τὸν συνόντα ἀποδεῖξαι, οὐδέ γε ἀναισχυντίαν καὶ ἀκρασίαν παρεχόμενον ἐγκρατῆ καὶ αἰδούμενον τὸν ἐρώμενον ποιῆσαι.", "st": "8.27"}, {"sp": "N", "t": "ἐπιθυμῶ δέ σοι, ἔφη, ὦ Καλλία, καὶ μυθολογῆσαι ὡς οὐ μόνον ἄνθρωποι ἀλλὰ καὶ θεοὶ καὶ ἥρωες τὴν τῆς ψυχῆς φιλίαν περὶ πλείονος ἢ τὴν τοῦ σώματος χρῆσιν ποιοῦνται.", "st": "8.28"}, {"sp": "N", "t": "Ζεύς τε γὰρ ὅσων μὲν θνητῶν οὐσῶν μορφῆς ἠράσθη, συγγενόμενος εἴα αὐτὰς θνητὰς εἶναι· ὅσων δὲ ψυχαῖς ἀγαθαῖς ἀγασθείη, ἀθανάτους τούτους ἐποίει· ὧν Ἡρακλῆς μὲν καὶ Διόσκουροί εἰσι, λέγονται δὲ καὶ ἄλλοι·", "st": "8.29"}, {"sp": "N", "t": "καὶ ἐγὼ δέ φημι καὶ Γανυμήδην οὐ σώματος ἀλλὰ ψυχῆς ἕνεκα ὑπὸ Διὸς εἰς Ὄλυμπον ἀνενεχθῆναι. μαρτυρεῖ δὲ καὶ τοὔνομα αὐτοῦ· ἔστι μὲν γὰρ δήπου καὶ Ὁμήρωι γάνυται δέ τ᾽ ἀκούων. τοῦτο δὲ φράζει ὅτι ἥδεται δέ τ᾽ ἀκούων. ἔστι δὲ καὶ ἄλλοθί που πυκινὰ φρεσὶ μήδεα εἰδώς. τοῦτο δ᾽ αὖ λέγει σοφὰ φρεσὶ βουλεύματα εἰδώς. ἐξ οὖν συναμφοτέρων τούτων οὐχ ἡδυσώματος ὀνομασθεὶς ὁ Γανυμήδης ἀλλ᾽ ἡδυγνώμων ἐν θεοῖς τετίμηται.", "st": "8.30"}, {"sp": "N", "t": "ἀλλὰ μήν, ὦ Νικήρατε, καὶ Ἀχιλλεὺς Ὁμήρωι πεποίηται οὐχ ὡς παιδικοῖς Πατρόκλωι ἀλλ᾽ ὡς ἑταίρωι ἀποθανόντι ἐκπρεπέστατα τιμωρῆσαι. καὶ Ὀρέστης δὲ καὶ Πυλάδης καὶ Θησεὺς καὶ Πειρίθους καὶ ἄλλοι δὲ πολλοὶ τῶν ἡμιθέων οἱ ἄριστοι ὑμνοῦνται οὐ διὰ τὸ συγκαθεύδειν ἀλλὰ διὰ τὸ ἄγασθαι ἀλλήλους τὰ μέγιστα καὶ κάλλιστα κοινῆι διαπεπρᾶχθαι.", "st": "8.31"}, {"sp": "N", "t": "τί δέ, τὰ νῦν καλὰ ἔργα οὐ πάντ᾽ ἂν εὕροι τις ἕνεκα ἐπαίνου ὑπὸ τῶν καὶ πονεῖν καὶ κινδυνεύειν ἐθελόντων πραττόμενα μᾶλλον ἢ ὑπὸ τῶν ἐθιζομένων ἡδονὴν ἀντ᾽ εὐκλείας αἱρεῖσθαι; καίτοι Παυσανίας γε ὁ Ἀγάθωνος τοῦ ποιητοῦ ἐραστὴς ἀπολογούμενος ὑπὲρ τῶν ἀκρασίαι ἐγκαλινδουμένων εἴρηκεν ὡς καὶ στράτευμα ἀλκιμώτατον ἂν γένοιτο ἐκ παιδικῶν τε καὶ ἐραστῶν.", "st": "8.32"}, {"sp": "N", "t": "τούτους γὰρ ἂν ἔφη οἴεσθαι μάλιστα αἰδεῖσθαι ἀλλήλους ἀπολείπειν, θαυμαστὰ λέγων, εἴ γε οἱ ψόγου τε ἀφροντιστεῖν καὶ ἀναισχυντεῖν πρὸς ἀλλήλους ἐθιζόμενοι, οὗτοι μάλιστα αἰσχυνοῦνται αἰσχρόν τι ποιεῖν.", "st": "8.33"}, {"sp": "N", "t": "καὶ μαρτύρια δὲ ἐπήγετο ὡς ταῦτα ἐγνωκότες εἶεν καὶ Θηβαῖοι καὶ Ἠλεῖοι· συγκαθεύδοντας γοῦν αὐτοῖς ὅμως παρατάττεσθαι ἔφη τὰ παιδικὰ εἰς τὸν ἀγῶνα, οὐδὲν τοῦτο σημεῖον λέγων ὅμοιον. ἐκείνοις μὲν γὰρ ταῦτα νόμιμα, ἡμῖν δ᾽ ἐπονείδιστα. δοκοῦσι δ᾽ ἔμοιγε οἱ μὲν παραταττόμενοι ἀπιστοῦσιν ἐοικέναι μὴ χωρὶς γενόμενοι οἱ ἐρώμενοι οὐκ ἀποτελῶσι τὰ τῶν ἀγαθῶν ἀνδρῶν ἔργα.", "st": "8.34"}, {"sp": "N", "t": "Λακεδαιμόνιοι δὲ οἱ νομίζοντες, ἐὰν καὶ ὀρεχθῆι τις σώματος, μηδενὸς ἂν ἔτι καλοῦ κἀγαθοῦ τοῦτον τυχεῖν, οὕτω τελέως τοὺς ἐρωμένους ἀγαθοὺς ἀπεργάζονται ὡς καὶ μετὰ ξένων κἂν μὴ ἐν τῆι αὐτῆι ταχθῶσι τῶι ἐραστῆι, ὁμοίως αἰδοῦνται τοὺς παρόντας ἀπολείπειν. θεὰν γὰρ οὐ τὴν Ἀναίδειαν ἀλλὰ τὴν Αἰδῶ νομίζουσι.", "st": "8.35"}, {"sp": "N", "t": "δοκοῦμεν δ᾽ ἄν μοι πάντες ὁμόλογοι γενέσθαι περὶ ὧν λέγω, εἰ ὧδε ἐπισκοποῖμεν, τῶι ποτέρως παιδὶ φιληθέντι μᾶλλον ἄν τις πιστεύσειεν ἢ χρήματα ἢ τέκνα ἢ χάριτας παρακατατίθεσθαι. ἐγὼ μὲν γὰρ οἶμαι καὶ αὐτὸν τὸν τῶι εἴδει τοῦ ἐρωμένου χρώμενον μᾶλλον ἂν ταῦτα πάντα τῶι τὴν ψυχὴν ἐρασμίωι πιστεῦσαι.", "st": "8.36"}, {"sp": "N", "t": "σοί γε μήν, ὦ Καλλία, δοκεῖ μοι ἄξιον εἶναι καὶ θεοῖς χάριν εἰδέναι ὅτι σοι Αὐτολύκου ἔρωτα ἐνέβαλον. ὡς μὲν γὰρ φιλότιμός ἐστιν εὔδηλον, ὃς τοῦ κηρυχθῆναι ἕνεκα νικῶν παγκράτιον πολλοὺς μὲν πόνους, πολλὰ δ᾽ ἄλγη ἀνέχεται.", "st": "8.37"}, {"sp": "N", "t": "εἰ δὲ οἴοιτο μὴ μόνον ἑαυτὸν καὶ τὸν πατέρα κοσμήσειν, ἀλλ᾽ ἱκανὸς γενήσεσθαι δι᾽ ἀνδραγαθίαν καὶ φίλους εὖ ποιεῖν καὶ τὴν πατρίδα αὔξειν τροπαῖα τῶν πολεμίων ἱστάμενος, καὶ διὰ ταῦτα περίβλεπτός τε καὶ ὀνομαστὸς ἔσεσθαι καὶ ἐν Ἕλλησι καὶ ἐν βαρβάροις, πῶς οὐκ οἴει αὐτόν, ὅντιν᾽ ἡγοῖτο εἰς ταῦτα συνεργὸν εἶναι κράτιστον, τοῦτον ταῖς μεγίσταις ἂν τιμαῖς περιέπειν;", "st": "8.38"}, {"sp": "N", "t": "εἰ οὖν βούλει τούτωι ἀρέσκειν, σκεπτέον μέν σοι ποῖα ἐπιστάμενος Θεμιστοκλῆς ἱκανὸς ἐγένετο τὴν Ἑλλάδα ἐλευθεροῦν, σκεπτέον δὲ ποῖά ποτε εἰδὼς Περικλῆς κράτιστος ἐδόκει τῆι πατρίδι σύμβουλος εἶναι, ἀθρητέον δὲ καὶ πῶς ποτε Σόλων φιλοσοφήσας νόμους κρατίστους τῆι πόλει κατέθηκεν, ἐρευνητέον δὲ καὶ ποῖα Λακεδαιμόνιοι ἀσκοῦντες κράτιστοι δοκοῦσιν ἡγεμόνες εἶναι· προξενεῖς δὲ καὶ κατάγονται ἀεὶ παρὰ σοὶ οἱ κράτιστοι αὐτῶν.", "st": "8.39"}, {"sp": "N", "t": "ὡς μὲν οὖν σοι ἡ πόλις ταχὺ ἂν ἐπιτρέψειεν αὑτήν, εἰ βούλει, εὖ ἴσθι. τὰ μέγιστα γάρ σοι ὑπάρχει· εὐπατρίδης εἶ, ἱερεὺς θεῶν τῶν ἀπ᾽ Ἐρεχθέως, οἳ καὶ ἐπὶ τὸν βάρβαρον σὺν Ἰάκχωι ἐστράτευσαν, καὶ νῦν ἐν τῆι ἑορτῆι ἱεροπρεπέστατος δοκεῖς εἶναι τῶν προγεγενημένων, καὶ σῶμα ἀξιοπρεπέστατον μὲν ἰδεῖν τῆς πόλεως ἔχεις, ἱκανὸν δὲ μόχθους ὑποφέρειν.", "st": "8.40"}, {"sp": "N", "t": "εἰ δ᾽ ὑμῖν δοκῶ σπουδαιολογῆσαι μᾶλλον ἢ παρὰ πότον πρέπει, μηδὲ τοῦτο θαυμάζετε. ἀγαθῶν γὰρ φύσει καὶ τῆς ἀρετῆς φιλοτίμως ἐφιεμένων ἀεί ποτε τῆι πόλει συνεραστὴς ὢν διατελῶ.", "st": "8.41"}, {"sp": "N", "t": "οἱ μὲν δὴ ἄλλοι περὶ τῶν ῥηθέντων διελέγοντο, ὁ δ᾽ Αὐτόλυκος κατεθεᾶτο τὸν Καλλίαν. καὶ ὁ Καλλίας δὲ παρορῶν εἰς ἐκεῖνον εἶπεν· Οὐκοῦν σύ με, ὦ Σώκρατες, μαστροπεύσεις πρὸς τὴν πόλιν, ὅπως πράττω τὰ πολιτικὰ καὶ ἀεὶ ἀρεστὸς ὦ αὐτῆι;", "st": "8.42"}, {"sp": "N", "t": "Ναὶ μὰ Δί᾽, ἔφη, ἂν ὁρῶσί γέ σε μὴ τῶι δοκεῖν ἀλλὰ τῶι ὄντι ἀρετῆς ἐπιμελούμενον. ἡ μὲν γὰρ ψευδὴς δόξα ταχὺ ἐλέγχεται ὑπὸ τῆς πείρας· ἡ δ᾽ ἀληθὴς ἀνδραγαθία, ἂν μὴ θεὸς βλάπτηι, ἀεὶ ἐν ταῖς πράξεσι λαμπροτέραν τὴν εὔκλειαν συμπαρέχεται.", "st": "8.43"}, {"sp": "N", "t": "Οὗτος μὲν δὴ ὁ λόγος ἐνταῦθα ἔληξεν. Αὐτόλυκος δὲ (ἤδη γὰρ ὥρα ἦν αὐτῶι) ἐξανίστατο εἰς περίπατον· καὶ ὁ Λύκων ὁ πατὴρ αὐτῶι συνεξιὼν ἐπιστραφεὶς εἶπε· Νὴ τὴν Ἥραν, ὦ Σώκρατες, καλός γε κἀγαθὸς δοκεῖς μοι ἄνθρωπος εἶναι.", "st": "9.1"}, {"sp": "N", "t": "Ἐκ δὲ τούτου πρῶτον μὲν θρόνος τις ἔνδον κατετέθη, ἔπειτα δὲ ὁ Συρακόσιος εἰσελθὼν εἶπεν· Ὦ ἄνδρες, Ἀριάδνη εἴσεισιν εἰς τὸν ἑαυτῆς τε καὶ Διονύσου θάλαμον· μετὰ δὲ τοῦθ᾽ ἥξει Διόνυσος ὑποπεπωκὼς παρὰ θεοῖς καὶ εἴσεισι πρὸς αὐτήν, ἔπειτα παιξοῦνται πρὸς ἀλλήλους.", "st": "9.2"}, {"sp": "N", "t": "ἐκ τούτου πρῶτον μὲν ἡ Ἀριάδνη ὡς νύμφη κεκοσμημένη παρῆλθε καὶ ἐκαθέζετο ἐπὶ τοῦ θρόνου. οὔπω δὲ φαινομένου τοῦ Διονύσου ηὐλεῖτο ὁ βακχεῖος ῥυθμός. ἔνθα δὴ ἠγάσθησαν τὸν ὀρχηστοδιδάσκαλον. εὐθὺς μὲν γὰρ ἡ Ἀριάδνη ἀκούσασα τοιοῦτόν τι ἐποίησεν ὡς πᾶς ἂν ἔγνω ὅτι ἀσμένη ἤκουσε· καὶ ὑπήντησε μὲν οὒ οὐδὲ ἀνέστη, δήλη δ᾽ ἦν μόλις ἠρεμοῦσα.", "st": "9.3"}, {"sp": "N", "t": "ἐπεί γε μὴν κατεῖδεν αὐτὴν ὁ Διόνυσος, ἐπιχορεύσας ὥσπερ ἂν εἴ τις φιλικώτατα ἐκαθέζετο ἐπὶ τῶν γονάτων, καὶ περιλαβὼν ἐφίλησεν αὐτήν. ἡ δ᾽ αἰδουμένηι μὲν ἐώικει, ὅμως δὲ φιλικῶς ἀντιπεριελάμβανεν. οἱ δὲ συμπόται ὁρῶντες ἅμα μὲν ἐκρότουν, ἅμα δὲ ἐβόων αὖθις.", "st": "9.4"}, {"sp": "N", "t": "ὡς δὲ ὁ Διόνυσος ἀνιστάμενος συνανέστησε μεθ᾽ ἑαυτοῦ τὴν Ἀριάδνην, ἐκ τούτου δὴ φιλούντων τε καὶ ἀσπαζομένων ἀλλήλους σχήματα παρῆν θεάσασθαι. οἱ δ᾽ ὁρῶντες ὄντως καλὸν μὲν τὸν Διόνυσον, ὡραίαν δὲ τὴν Ἀριάδνην, οὐ σκώπτοντας δὲ ἀλλ᾽ ἀληθινῶς τοῖς στόμασι φιλοῦντας, πάντες ἀνεπτερωμένοι ἐθεῶντο.", "st": "9.5"}, {"sp": "N", "t": "καὶ γὰρ ἤκουον τοῦ Διονύσου μὲν ἐπερωτῶντος αὐτὴν εἰ φιλεῖ αὐτόν, τῆς δὲ οὕτως ἐπομνυούσης ⟨ὥστε⟩ μὴ μόνον τὸν Διόνυσον ἀλλὰ καὶ τοὺς παρόντας ἅπαντας συνομόσαι ἂν ἦ μὴν τὸν παῖδα καὶ τὴν παῖδα ὑπ᾽ ἀλλήλων φιλεῖσθαι. ἐώικεσαν γὰρ οὐ δεδιδαγμένοις τὰ σχήματα ἀλλ᾽ ἐφειμένοις πράττειν ἃ πάλαι ἐπεθύμουν.", "st": "9.6"}, {"sp": "N", "t": "τέλος δὲ οἱ συμπόται ἰδόντες περιβεβληκότας τε ἀλλήλους καὶ ὡς εἰς εὐνὴν ἀπιόντας, οἱ μὲν ἄγαμοι γαμεῖν ἐπώμνυσαν, οἱ δὲ γεγαμηκότες ἀναβάντες ἐπὶ τοὺς ἵππους ἀπήλαυνον πρὸς τὰς ἑαυτῶν γυναῖκας, ὅπως τούτων τύχοιεν. Σωκράτης δὲ καὶ τῶν ἄλλων οἱ ὑπομείναντες πρὸς Λύκωνα καὶ τὸν υἱὸν σὺν Καλλίαι περιπατήσοντες ἀπῆλθον. αὕτη τοῦ τότε συμποσίου κατάλυσις ἐγένετο.", "st": "9.7"}],[]);})();